(function(){
const R4=id=>{if(!S.npc[id])S.npc[id]={met:false,like:0,trust:0,talks:0,truth:false};return S.npc[id]};
const met=id=>!!(S.npc[id]&&S.npc[id].met);
const today=k=>S.flags['tx4_'+k]===dayIndex();
const mark=k=>{S.flags['tx4_'+k]=dayIndex()};
const ONCE=k=>()=>today(k)?t(`今天已经来过了`,`You've already done that today`,`Já fizeste isso hoje`):true;
const NIGHT=()=>S.slot===2||t(`只在夜晚`,`Nights only`,`Só à noite`);
const DAY=()=>S.slot<2||t(`天黑了，明天再来`,`It's dark — come back tomorrow`,`Já é noite — volta amanhã`);
const sellLine=r=>r.sold?t(`卖出 ${r.sold} 份，收入 $${r.cash}`,`Sold ${r.sold} portions for $${r.cash}`,`Vendeste ${r.sold} doses por $${r.cash}`):t(`冷藏箱是空的，什么也没卖出去`,`The cooler is empty — you sell nothing`,`A geleira está vazia — não vendes nada`);
const buyLine=(c,q,n)=>c?t(`花 $${c} 买下 ${q} 份${n[0]}`,`Bought ${q} units of ${n[1].toLowerCase()} for $${c}`,`Compraste ${q} unidades de ${n[2].toLowerCase()} por $${c}`):t(`钱不够，只好空手走`,`Not enough cash — you leave empty-handed`,`Não tens dinheiro — sais de mãos vazias`);
const W=()=>(S.tripWith&&NPCS[S.tripWith])?S.tripWith:null;
const WN=()=>W()?SH(W()):t(`同伴`,`your companion`,`quem vem contigo`);
const NEEDW=()=>W()?true:t(`需要有人同行`,`Needs a travel companion`,`Precisas de companhia na viagem`);
// recurring storylines: one stage per visit
const stg=k=>S.flags['tx4_'+k]||0;
const visits=c=>(S.visited&&S.visited[c])||0;
const arcReq=(k,c)=>()=>{if(stg(k)>=4)return today(k+'_hang')?t(`今天已经见过了`,`You've already seen them today`,`Já estiveste com essa pessoa hoje`):true;
 if(S.flags['tx4_'+k+'_v']!==undefined&&S.flags['tx4_'+k+'_v']===visits(c))return t(`这一趟已经见过了，下次来再说`,`You've already seen them this trip — next visit`,`Já estiveste com essa pessoa nesta viagem — na próxima`);return true};
const step=(k,c,f)=>()=>{R4(k).met=true;S.flags['tx4_'+k]=Math.min(4,stg(k)+1);S.flags['tx4_'+k+'_v']=visits(c);if(f)f()};
const metaArc=(k)=>t(`连续故事 · 第 ${Math.min(4,stg(k)+1)}/4 段`,`Storyline · part ${Math.min(4,stg(k)+1)} of 4`,`História · parte ${Math.min(4,stg(k)+1)} de 4`);
const hang=(k,lines)=>{mark(k+'_hang');const o=pick(lines);addLike(k,0.5);if(o[1])o[1]();return say(tt(NPCS[k].n),o[0],t(`老朋友`,`An old friend`,`Um velho amigo`))};

/* ================= EL PASO ================= */
const sunBowl=()=>inSeason(26,29);
const marScene=()=>{const s=stg('maricela'),C='elpaso',M='maricela';
 if(s>=4)return hang(M,[
  [[t(`玛丽塞拉在改卷子，红笔在桌上滚来滚去。“我的学生还在问那个葡萄牙厨师什么时候再来。”她给你倒了一杯加肉桂的咖啡。`,`Maricela is grading papers, her red pen rolling across the desk. "My kids still ask when the Portuguese cook is coming back." She pours you coffee with cinnamon in it.`,`A Maricela está a corrigir testes, a caneta vermelha a rolar pela mesa. «Os meus alunos ainda perguntam quando volta o cozinheiro português.» Serve-te um café com canela.`)],()=>stat('saud',-2)],
  [[t(`她带你去吃早饭，指着窗外的富兰克林山：“你看，山还在原地。人搬来搬去，山不动。我外婆说这是唯一不用签证的东西。”`,`She takes you to breakfast and points at the Franklin Mountains outside. "See? The mountains stay put. People move around; mountains don't. My grandma says they're the only thing that never needs a visa."`,`Leva-te a tomar o pequeno-almoço e aponta para as Franklin lá fora. «Vês? A serra não sai do sítio. As pessoas mudam-se; as montanhas não. A minha avó diz que são a única coisa que nunca precisa de visto.»`)],()=>stat('tex',1)]]);
 if(s===0)return {title:t(`圣埃利萨里奥礼拜堂前`,`Outside the San Elizario chapel`,`Diante da capela de San Elizario`),meta:metaArc(M),
  text:[t(`礼拜堂的白墙被太阳晒得发亮。三十个高中生坐在台阶上，一个穿牛仔外套的女老师站在他们前面，手里拿着一张复印的老地图。“1598 年，一支西班牙远征队走过沙漠，在这附近的河边吃了一顿感恩的饭。比普利茅斯早了二十多年。所以下次有人跟你们说感恩节是东海岸发明的——”`,`The chapel's white walls glare in the sun. Thirty high-schoolers sit on the steps, and a teacher in a denim jacket stands in front of them holding a photocopied old map. "In 1598 a Spanish expedition crossed the desert and held a thanksgiving meal by the river near here. More than twenty years before Plymouth. So next time somebody tells y'all Thanksgiving was invented back east—"`,`As paredes brancas da capela brilham ao sol. Trinta alunos de liceu estão sentados nos degraus e uma professora de casaco de ganga está à frente deles com um mapa antigo fotocopiado. «Em 1598 uma expedição espanhola atravessou o deserto e fez uma refeição de ação de graças junto ao rio, aqui perto. Mais de vinte anos antes de Plymouth. Por isso, da próxima vez que vos disserem que o Dia de Ação de Graças foi inventado na costa leste—»`),
   t(`她看见你在拍照，眼睛一亮：“正好。先生，您从哪儿来？”三十个脑袋一起转过来。`,`She spots you taking a photo and her eyes light up. "Perfect timing. Sir, where are you from?" Thirty heads turn at once.`,`Ela vê-te a tirar uma fotografia e os olhos dela acendem-se. «Mesmo a tempo. O senhor é de onde?» Trinta cabeças viram-se ao mesmo tempo.`)],
  choices:[
   {t:t(`说实话：里斯本来的，舅舅死了，留下一家店和一张只认店的签证`,`Tell the truth: from Lisbon; your uncle died and left you a shop and a visa that only sees the shop`,`Dizer a verdade: de Lisboa; o teu tio morreu e deixou-te um restaurante e um visto que só vê o restaurante`),fx:step(M,C,()=>{addTrust(M,2);addLike(M,1);stat('saud',-1)}),next:()=>say(t(`玛丽塞拉·奥尔蒂斯`,`Maricela Ortiz`,`Maricela Ortiz`),[t(`学生们安静了。她点点头，像是你替她把课讲完了。“这就是我说的边境。不是一条线，是一张纸。”下课后她走过来伸出手：“玛丽塞拉·奥尔蒂斯。我家一半住在这边，一半住在华雷斯。下次来，我请你吃我妈做的饭。”`,`The kids go quiet. She nods, as if you'd finished her lesson for her. "That's what I mean by a border. It's not a line. It's a piece of paper." After class she comes over and offers her hand. "Maricela Ortiz. Half my family lives on this side, half in Juárez. Next time you're here, my mom's cooking."`,`Os miúdos calam-se. Ela acena, como se lhe tivesses acabado a aula. «É isto que eu quero dizer com fronteira. Não é uma linha. É um papel.» No fim vem ter contigo e estende a mão. «Maricela Ortiz. Metade da minha família vive deste lado, metade em Juárez. Da próxima vez que vieres, a minha mãe cozinha.»`)])},
   {t:t(`开玩笑：“我是为了玉米卷饼来的。”`,`Joke: "I came for the tacos."`,`Brincar: «Vim pelos tacos.»`),fx:step(M,C,()=>{addLike(M,2);S.rep+=1}),next:()=>say(t(`玛丽塞拉·奥尔蒂斯`,`Maricela Ortiz`,`Maricela Ortiz`),[t(`全班笑翻。她也笑，然后说：“那你来对地方了，但你说错了词。在这儿，那叫早饭、午饭和晚饭。”她把名字写在你的手背上：玛丽塞拉·奥尔蒂斯，历史老师。`,`The whole class cracks up. So does she, then says, "Then you came to the right place, but you've got the word wrong. Out here we call that breakfast, lunch and dinner." She writes her name on the back of your hand: Maricela Ortiz, history teacher.`,`A turma inteira desata a rir. Ela também, e depois diz: «Então vieste ao sítio certo, mas enganaste-te na palavra. Aqui chamamos-lhe pequeno-almoço, almoço e jantar.» Escreve-te o nome nas costas da mão: Maricela Ortiz, professora de História.`)])},
   {t:t(`用德州腔回答：“How y'all doin'（大家好啊）？圣鲁伊斯来的。”`,`Answer Texas-style: "How y'all doin'? San Luís, up on I-35."`,`Responder à texana: «How y'all doin'? Sou de San Luís, na I-35.»`),req:()=>S.stats.tex>=35||NEED(t(`德州味 35`,`Texanness 35`,`Texanidade 35`)),fx:step(M,C,()=>{addLike(M,1);addTrust(M,1);stat('tex',2)}),next:()=>say(t(`玛丽塞拉·奥尔蒂斯`,`Maricela Ortiz`,`Maricela Ortiz`),[t(`“口音不对，”一个男生喊，“他是装的！”老师笑着问你到底哪儿人。你只好承认里斯本。“看见没，”她对学生说，“德州话是可以学会的。这就是融入。”她叫玛丽塞拉，说下次来一定要找她。`,`"That accent's fake!" a boy shouts. The teacher laughs and asks where you're really from. You confess: Lisbon. "See?" she tells the class. "Texan can be learned. That's what belonging looks like." Her name is Maricela, and she makes you promise to look her up next time.`,`«Esse sotaque é falso!», grita um rapaz. A professora ri-se e pergunta-te de onde és mesmo. Confessas: Lisboa. «Estão a ver?», diz ela à turma. «O texano aprende-se. Pertencer é isto.» Chama-se Maricela e faz-te prometer que a procuras da próxima vez.`)])}]};
 if(s===1)return {title:t(`查米萨尔国家纪念地`,`Chamizal National Memorial`,`Memorial Nacional do Chamizal`),meta:metaArc(M),
  text:[t(`玛丽塞拉带你走到河边。格兰德河在这里被关进一条水泥渠，水又浅又浑，对岸就是华雷斯的房子，近得能看清晾着的衣服。“这条河以前会自己改道，”她说，“河一挪，国界就跟着挪。一百年里两国吵了几十年，到 1963 年才签条约，把河道用水泥固定住。我外婆说：她从来没有越过边境，是边境越过了她。”`,`Maricela walks you down to the river. Here the Rio Grande is locked in a concrete channel, shallow and muddy, and the houses of Juárez are so close you can see the laundry on the lines. "This river used to change course on its own," she says. "The river moved, the border moved with it. The two countries argued for decades until a treaty in 1963, and then they poured concrete so the river would stay put. My grandma says she never crossed the border — the border crossed her."`,`A Maricela leva-te até ao rio. Aqui o Rio Grande está preso num canal de betão, raso e barrento, e as casas de Juárez estão tão perto que se vê a roupa a secar. «Este rio mudava de leito sozinho», diz ela. «O rio mexia-se e a fronteira mexia-se com ele. Os dois países discutiram durante décadas até um tratado em 1963, e depois deitaram betão para o rio ficar quieto. A minha avó diz que nunca atravessou a fronteira — foi a fronteira que a atravessou a ela.»`),
   t(`“我外婆每个星期天过桥来做弥撒，再过桥回去。七十年了。你呢？你家人什么时候来看你？”`,`"Every Sunday my grandma crosses the bridge for Mass and crosses back. Seventy years. And you? When does your family come see you?"`,`«Todos os domingos a minha avó atravessa a ponte para ir à missa e volta. Setenta anos. E tu? Quando é que a tua família te vem ver?»`)],
  choices:[
   {t:t(`讲若泽：一个人离开里斯本，再也没回去`,`Talk about José: a man who left Lisbon and never went back`,`Falar do José: um homem que saiu de Lisboa e nunca voltou`),fx:step(M,C,()=>{addTrust(M,2);stat('saud',-2)}),next:()=>say(t(`河边`,`By the river`,`Junto ao rio`),[t(`她听完很久没说话。“有些人过不了的不是桥，是自己。”她捡起一块石头，没扔，揣进了口袋。“你舅舅给你留了店，也是给你留了一座桥。别学他。”`,`She's quiet a long while after you finish. "Some people can't cross a bridge. Some can't cross themselves." She picks up a stone, doesn't throw it, puts it in her pocket. "Your uncle left you a shop. That's a bridge too. Don't be like him."`,`Fica muito tempo calada quando acabas. «Há quem não consiga atravessar uma ponte. E há quem não consiga atravessar-se a si próprio.» Apanha uma pedra, não a atira, mete-a no bolso. «O teu tio deixou-te um restaurante. Isso também é uma ponte. Não sejas como ele.»`)])},
   {t:t(`讲母亲：她在里斯本，身体不好，你却过不去`,`Talk about your mother: in Lisbon, not well, and you can't get there`,`Falar da tua mãe: em Lisboa, adoentada, e tu sem poder ir`),fx:step(M,C,()=>{addLike(M,2);stat('saud',2)}),next:()=>say(t(`河边`,`By the river`,`Junto ao rio`),[t(`“我懂，”她说，“我爸病的那年，我站在桥这头，手里拿着护照，就是不敢走——怕回不来上班。”她把手机里外婆的照片给你看。“给你妈妈打电话。不要发短信，打电话。”`,`"I know," she says. "The year my dad got sick I stood at this end of the bridge with my passport in my hand and couldn't go — scared I wouldn't make it back to work." She shows you a photo of her grandma on her phone. "Call your mom. Don't text. Call."`,`«Eu sei», diz ela. «No ano em que o meu pai adoeceu, fiquei deste lado da ponte com o passaporte na mão e não fui — com medo de não voltar a tempo para o trabalho.» Mostra-te uma fotografia da avó no telemóvel. «Liga à tua mãe. Não mandes mensagem. Liga.»`)])},
]};
 if(s===2)return {title:t(`第二区，玛丽塞拉母亲的厨房`,`Segundo Barrio, Maricela's mother's kitchen`,`Segundo Barrio, a cozinha da mãe da Maricela`),meta:metaArc(M),
  text:[t(`第二区是埃尔帕索最老的街区之一，墙上画满了壁画。玛丽塞拉的母亲个子很小，围裙很大。她不叠卷，把玉米饼、红辣椒酱和奶酪一层一层摞起来，最上面盖一个煎蛋。“这是我们这边的做法，”她说，“新墨西哥人说是他们的，我们不跟他们吵。”`,`Segundo Barrio is one of El Paso's oldest neighbourhoods, its walls covered in murals. Maricela's mother is tiny; her apron is not. She doesn't roll the enchiladas — she stacks them: tortilla, red chile, cheese, again and again, with a fried egg on top. "This is how we do it on this side," she says. "New Mexicans say it's theirs. We don't argue with them."`,`O Segundo Barrio é um dos bairros mais antigos de El Paso, com as paredes cheias de murais. A mãe da Maricela é pequenina; o avental não. Não enrola as enchiladas — empilha-as: tortilha, chile vermelho, queijo, outra vez e outra vez, com um ovo estrelado por cima. «É assim que se faz deste lado», diz. «Os do Novo México dizem que é deles. Não discutimos com eles.»`),
   t(`吃饭时玛丽塞拉的表姐也在，她在移民律师事务所做助理。她听说你的签证，放下叉子：“条约投资者签证？那你记住三件事：账要干净，税要按时报，店不能停。它看的不是你，是你的账本。”`,`Maricela's cousin joins for dinner; she's a paralegal at an immigration firm. When she hears about your visa she puts her fork down. "Treaty investor? Then remember three things: clean books, taxes on time, and the shop never closes. It doesn't look at you. It looks at your ledger."`,`Ao jantar está também a prima da Maricela, que é assistente num escritório de advogados de imigração. Quando ouve falar do teu visto pousa o garfo. «Investidor ao abrigo de tratado? Então lembra-te de três coisas: contas limpas, impostos a horas e o restaurante nunca fecha. Ele não olha para ti. Olha para o teu livro de contas.»`),
   ...(met('ines')?[t(`玛丽塞拉看了你一眼：“那个从里斯本来的女孩呢？她知道她要是留下，也得挂在你这张纸上吗？”你想起伊内丝，没回答。`,`Maricela glances at you. "And the girl from Lisbon? Does she know if she stays, she'll be hanging on that same piece of paper?" You think of Inês and don't answer.`,`A Maricela olha para ti. «E a rapariga de Lisboa? Ela sabe que, se ficar, fica pendurada no mesmo papel?» Pensas na Inês e não respondes.`)]:[])],
  choices:[
   {t:t(`系上围裙，跟她母亲一层一层学`,`Put on an apron and learn it layer by layer`,`Pôr um avental e aprender camada a camada`),fx:step(M,C,()=>{learnDish('tx4_ench');stat('oficio',3);addLike(M,1)}),next:()=>say(t(`叠层恩奇拉达`,`Stacked enchiladas`,`Enchiladas empilhadas`),[t(`辣椒要先烤再泡，酱不能有一点苦。她拍拍你的手：“你手稳。你舅舅一定也是。”你没告诉她你舅舅是谁，她却像早就知道。`,`The chiles are toasted first, then soaked; the sauce mustn't have a trace of bitterness. She pats your hand. "Steady hands. Your uncle must've had them too." You never told her who your uncle was, but she talks as if she knows.`,`Os chiles tostam-se primeiro e depois demolham-se; o molho não pode ter ponta de amargo. Ela dá-te uma palmadinha na mão. «Mão firme. O teu tio também devia ter.» Nunca lhe disseste quem era o teu tio, mas ela fala como se soubesse.`)],t(`学会：叠层红辣椒恩奇拉达 · 手艺 +3`,`Learned: Stacked red-chile enchiladas · Craft +3`,`Aprendeste: Enchiladas empilhadas · Ofício +3`))},
   {t:t(`拿出本子，把表姐说的签证要点一条条记下来`,`Get out a notebook and write down every visa point the cousin makes`,`Tirar um caderno e apontar tudo o que a prima diz sobre o visto`),fx:step(M,C,()=>{learnDish('tx4_ench');S.flags.tx4_visaTips=1;addTrust(M,1);if(met('grace'))addTrust('grace',1);if(met('ines'))addLike('ines',1)}),next:()=>say(t(`三条规矩`,`Three rules`,`Três regras`),[t(`表姐又说了一个钟头：配偶怎么跟签证、续签要准备几年的报税表、千万别让店停业超过一个月。你记了满满三页。走的时候玛丽塞拉的母亲往你包里塞了一张手写的菜谱。“账本要干净，酱也要干净。”`,`The cousin talks for another hour: how a spouse can follow the visa, how many years of tax returns a renewal needs, never to let the shop close for more than a month. You fill three pages. On your way out Maricela's mother slips a handwritten recipe into your bag. "Clean books, clean sauce."`,`A prima fala mais uma hora: como um cônjuge pode acompanhar o visto, quantos anos de declarações de impostos uma renovação pede, nunca deixar o restaurante fechado mais de um mês. Enches três páginas. À saída, a mãe da Maricela mete-te uma receita escrita à mão no saco. «Contas limpas, molho limpo.»`)],t(`学会：叠层红辣椒恩奇拉达 · 签证要点`,`Learned: Stacked enchiladas · visa notes`,`Aprendeste: Enchiladas empilhadas · notas sobre o visto`))}]};
 return {title:t(`玛丽塞拉的学校`,`Maricela's school`,`A escola da Maricela`),meta:metaArc(M),
  text:[t(`学期末的“家族传承日”。体育馆里摆了长桌，每个学生带来一样家里的东西：外公的铁路工牌、曾祖母从奇瓦瓦带来的念珠、一张 1940 年代的过桥证。玛丽塞拉请你掌勺，给六十个学生和家长做饭，还要你讲五分钟“为什么一个里斯本人会在德州烤肉”。`,`End-of-term Heritage Day. Long tables in the gym; every student has brought something from home: a grandfather's railroad badge, a rosary a great-grandmother carried from Chihuahua, a 1940s bridge-crossing card. Maricela has asked you to cook for sixty students and parents, and to give a five-minute talk on "why a man from Lisbon is grilling in Texas."`,`Fim de período, Dia da Herança. Mesas compridas no ginásio; cada aluno trouxe uma coisa de casa: o crachá de ferroviário de um avô, um terço que uma bisavó trouxe de Chihuahua, um cartão de travessia da ponte dos anos quarenta. A Maricela pediu-te para cozinhares para sessenta alunos e pais e para falares cinco minutos sobre «porque é que um homem de Lisboa está a grelhar no Texas».`)],
  choices:[
   {t:t(`做烤沙丁鱼和猪排包，讲真话：若泽、那张签证、你还没决定留不留`,`Grill sardines and pork sandwiches and tell the truth: José, the visa, how you haven't decided whether to stay`,`Grelhar sardinhas e bifanas e dizer a verdade: o José, o visto, que ainda não decidiste se ficas`),fx:step(M,C,()=>{S.cash+=450;S.wk.rev+=450;S.rep+=4;addTrust(M,2);stat('saud',-4);log('埃尔帕索学校外烩 +$450','El Paso school catering +$450','Catering na escola de El Paso +$450')}),next:()=>say(t(`家族传承日`,`Heritage Day`,`Dia da Herança`),[t(`你讲完，体育馆里很安静。然后一个坐轮椅的老太太用西班牙语说了一句什么，全场都鼓掌。玛丽塞拉翻译：“她说，没决定的人才是最诚实的。”`,`When you finish, the gym is silent. Then an old lady in a wheelchair says something in Spanish and the whole room applauds. Maricela translates: "She says the ones who haven't decided are the most honest."`,`Quando acabas, o ginásio está em silêncio. Depois uma senhora idosa numa cadeira de rodas diz qualquer coisa em espanhol e a sala inteira aplaude. A Maricela traduz: «Diz que quem ainda não decidiu é quem é mais honesto.»`),t(`临走她送你一张学生画的地图：古老的皇家内陆大道从墨西哥城一直画到圣菲，旁边有人用红笔加了一条线，从里斯本横跨大西洋，落在 35 号州际公路上。“挂在店里，”她说，“让人知道你也是一条路。”`,`Before you leave she gives you a map her students drew: the old Camino Real from Mexico City all the way to Santa Fe, and beside it someone has added a red line from Lisbon across the Atlantic, landing on I-35. "Hang it in the shop," she says. "So people know you're a road too."`,`Antes de saíres dá-te um mapa desenhado pelos alunos: o velho Camino Real desde a Cidade do México até Santa Fe, e ao lado alguém acrescentou uma linha vermelha de Lisboa, a atravessar o Atlântico, a pousar na I-35. «Pendura-o no restaurante», diz ela. «Para as pessoas saberem que tu também és uma estrada.»`)],t(`外烩 +$450 · 口碑 +4 · 乡愁 −4 · 玛丽塞拉的故事完结`,`Catering +$450 · Reputation +4 · Homesickness −4 · Maricela's story complete`,`Catering +$450 · Reputação +4 · Saudade −4 · História da Maricela concluída`))},
   {t:t(`做她母亲教的叠层恩奇拉达，但在上面放一勺葡式橄榄油蒜酱`,`Make her mother's stacked enchiladas, topped with a spoon of Portuguese garlic-and-olive-oil sauce`,`Fazer as enchiladas empilhadas da mãe dela, com uma colher de molho português de alho e azeite por cima`),req:()=>S.stats.oficio>=40||NEED(t(`手艺 40`,`Craft 40`,`Ofício 40`)),fx:step(M,C,()=>{learnDish('tx4_ench');S.cash+=520;S.wk.rev+=520;S.online+=6;S.rep+=3;addLike(M,2);stat('oficio',2);log('埃尔帕索学校外烩 +$520','El Paso school catering +$520','Catering na escola de El Paso +$520')}),next:()=>say(t(`家族传承日`,`Heritage Day`,`Dia da Herança`),[t(`她母亲尝了一口，眯起眼，什么都没说，又拿了第二块。玛丽塞拉说这是她妈妈能给出的最高评价。家长们拍了上百张照片，有一半配文写着“埃尔帕索遇见里斯本”。`,`Her mother takes a bite, narrows her eyes, says nothing, and takes a second piece. Maricela says that's the highest praise her mother gives. The parents take a hundred photos, half of them captioned "El Paso meets Lisbon."`,`A mãe dela prova, semicerra os olhos, não diz nada e tira um segundo pedaço. A Maricela diz que é o maior elogio que a mãe dá. Os pais tiram cem fotografias, metade com a legenda «El Paso encontra Lisboa».`),t(`临走她送你一张学生画的皇家内陆大道地图，上面有一条红线从里斯本连到 35 号州际公路。“挂在店里。”`,`Before you go she gives you the students' map of the Camino Real, with a red line from Lisbon to I-35. "Hang it in the shop."`,`Antes de saíres dá-te o mapa do Camino Real dos alunos, com uma linha vermelha de Lisboa à I-35. «Pendura-o no restaurante.»`)],t(`外烩 +$520 · 线上评分 +6 · 口碑 +3 · 玛丽塞拉的故事完结`,`Catering +$520 · Online +6 · Reputation +3 · Maricela's story complete`,`Catering +$520 · Online +6 · Reputação +3 · História da Maricela concluída`))},
]};
};
Object.assign(CITIES,{
 elpaso:{
  n:t(`埃尔帕索`,`El Paso`,`El Paso`), region:'west', miles:575, trip:'overnight', hotel:95,
  desc:t(`德州最西端的城市，和墨西哥的华雷斯隔着格兰德河。夜里两座城的灯连成一片，分不清哪边是哪国。`,`Texas's westernmost city, facing Ciudad Juárez across the Rio Grande. At night the two cities' lights run together and you can't tell which country is which.`,`A cidade mais ocidental do Texas, frente a Ciudad Juárez do outro lado do Rio Grande. À noite as luzes das duas cidades fundem-se e já não se sabe que país é qual.`),
  arrive:()=>{const v=S.visited.elpaso||0;
   if(v<=1)return [t(`从圣安东尼奥上了 10 号州际公路，就是一整天的沙漠。过了佩科斯河，你手机上的时间自己往回跳了一个钟头——埃尔帕索用的是山地时间，连钟点都跟德州别处不一样。傍晚，富兰克林山从地平线上升起来，山脚下是两座城：一座讲英语，一座讲西班牙语，中间隔着一条你几乎看不见的河。`,`From San Antonio you take I-10 and it's desert all day. Past the Pecos your phone's clock jumps back an hour by itself — El Paso runs on Mountain Time; even the hours here differ from the rest of Texas. Towards evening the Franklin Mountains rise from the horizon, and at their feet lie two cities: one speaks English, one speaks Spanish, and between them runs a river you can hardly see.`,`De San Antonio apanhas a I-10 e é deserto o dia inteiro. Depois do Pecos o relógio do telemóvel recua uma hora sozinho — El Paso vive na hora da montanha; até as horas são diferentes do resto do Texas. Ao fim da tarde, as montanhas Franklin erguem-se no horizonte e, aos pés delas, duas cidades: uma fala inglês, outra fala espanhol, e entre as duas corre um rio que mal se vê.`)];
   return [t(`手机又往回跳了一个钟头。你已经学会了在埃尔帕索多睡一会儿。`,`Your phone jumps back an hour again. You've learned to sleep in a little in El Paso.`,`O telemóvel volta a recuar uma hora. Já aprendeste a dormir mais um bocadinho em El Paso.`),...(sunBowl()?[t(`满街都是太阳碗橄榄球赛的横幅，冬天的太阳照样很猛。`,`Sun Bowl banners hang all down the streets; even the winter sun here hits hard.`,`As ruas estão cheias de faixas do Sun Bowl; até o sol de inverno aqui bate forte.`)]:[])]},
  locs:[
   {id:'tx4_franklin', n:t(`富兰克林山`,`Franklin Mountains`,`Montanhas Franklin`), acts:[
    {id:'drive', n:t(`沿观景路看两座城`,`Take Scenic Drive over the two cities`,`Subir a Scenic Drive sobre as duas cidades`), cost:2, tip:t(`山腰上的观景路，夜里看灯海`,`The road along the mountainside; a sea of lights at night`,`A estrada na encosta; um mar de luzes à noite`),
     run:()=>({title:t(`观景路`,`Scenic Drive`,`Scenic Drive`),meta:t(`西德州 · 两国之间`,`West Texas · between two countries`,`Oeste do Texas · entre dois países`),
      text:[t(`富兰克林山整片划成了州立公园，据说是全美最大的城市公园。你站在半山腰的护栏边，脚下是埃尔帕索，再往南是华雷斯，两座城加起来两百多万人，灯一路铺到天边。山上有一颗巨大的灯星，每天晚上点亮。`,`The Franklin Mountains are one big state park, said to be the largest urban park in the country. You stand at the rail halfway up: El Paso at your feet, Juárez beyond, more than two million people between them, the lights running all the way to the edge of the sky. On the mountain behind you a giant star is lit every night.`,`As montanhas Franklin são um parque estadual inteiro, dizem que o maior parque urbano do país. Estás no varandim a meio da encosta: El Paso aos teus pés, Juárez mais além, mais de dois milhões de pessoas, as luzes a estenderem-se até ao fim do céu. Na serra atrás de ti há uma estrela gigante que se acende todas as noites.`),
       t(`你想起恩惠圣母观景台，从那里看过去也是一片灯，对岸是阿尔马达，中间隔着特茹河。原来每座城都有一个让人站着发呆的地方。`,`You think of the Senhora do Monte lookout in Lisbon — a sea of lights there too, Almada on the far bank, the Tagus in between. Every city, it turns out, has a place where people stand and stare.`,`Lembras-te do miradouro da Senhora do Monte — também um mar de luzes, Almada na outra margem, o Tejo pelo meio. Afinal, todas as cidades têm um sítio onde as pessoas ficam paradas a olhar.`)],
      choices:[
       {t:t(`给家里打个电话`,`Call home`,`Ligar para casa`),fx:()=>{stat('saud',-3);stat('charme',1)},next:()=>say(t(`电话`,`The call`,`A chamada`),t(`里斯本是凌晨。鲁伊迷迷糊糊接起来，听你描述了五分钟灯海，说：“你打电话就为了这个？”然后又说：“妈会喜欢的。明天我讲给她听。”`,`It's the small hours in Lisbon. Rui answers half-asleep, listens to you describe the lights for five minutes, and says, "You called to tell me that?" Then: "Mum'll love it. I'll tell her tomorrow."`,`Em Lisboa é de madrugada. O Rui atende meio a dormir, ouve-te descrever as luzes durante cinco minutos e diz: «Ligaste para me dizer isso?» E depois: «A mãe vai gostar. Conto-lhe amanhã.»`),t(`乡愁 −3 · 魅力 +1`,`Homesickness −3 · Charm +1`,`Saudade −3 · Charme +1`))},
       {t:t(`数一数哪些灯是哪个国家的`,`Try to work out whose lights are whose`,`Tentar perceber que luzes são de que país`),fx:()=>{stat('tex',2);stat('saud',1)},next:()=>say(t(`灯海`,`The lights`,`As luzes`),t(`你数到一半就放弃了。从这么高的地方看，国界只是一道暗一点的线，像一条皱纹。`,`You give up halfway. From up here the border is just a slightly darker line, like a wrinkle.`,`Desistes a meio. Cá de cima, a fronteira é só uma linha um pouco mais escura, como uma ruga.`),t(`德州味 +2 · 乡愁 +1`,`Texanness +2 · Homesickness +1`,`Texanidade +2 · Saudade +1`))},
       {t:t(`和${WN()}靠在护栏上，等那颗星亮起来`,`Lean on the rail with ${WN()} and wait for the star to light`,`Encostar-te ao varandim com ${WN()} à espera de que a estrela se acenda`),req:NEEDW,fx:()=>{if(W()){addLike(W(),1);addTrust(W(),1)}stat('saud',-2)},next:()=>say(t(`山上的星`,`The star on the mountain`,`A estrela na serra`),t(`星亮起来的时候，${WN()}说：“你知道吗，我从来没离开过德州中部这么远。”风很大，你们谁都没提回去的事。`,`When the star comes on, ${WN()} says, "You know, I've never been this far from Central Texas." The wind is strong; neither of you mentions going back.`,`Quando a estrela se acende, ${WN()} diz: «Sabes, nunca estive tão longe do Texas Central.» O vento é forte; nenhum dos dois fala em voltar.`),t(`好感 +1 · 信任 +1 · 乡愁 −2`,`Affection +1 · Trust +1 · Homesickness −2`,`Afeto +1 · Confiança +1 · Saudade −2`))}]})},
    {id:'hike', n:t(`早上爬山`,`Morning hike`,`Caminhada de manhã`), cost:3, req:DAY, tip:t(`沙漠山路，带够水`,`Desert trail — bring water`,`Trilho de deserto — leva água`),
     run:()=>say(t(`沙漠山路`,`Desert trail`,`Trilho de deserto`),[inSeason(1,12)?t(`才九点，石头已经烫手。一个老人从山上下来，把他的半瓶水递给你：“第一次？来这儿的人都低估了太阳。”`,`It's only nine and the rocks already burn your hands. An old man coming down offers you his half bottle of water. "First time? Everybody underestimates the sun out here."`,`São só nove horas e as pedras já queimam as mãos. Um velho que vem a descer oferece-te meia garrafa de água. «Primeira vez? Toda a gente subestima o sol aqui.»`):t(`空气又干又凉，仙人掌、丝兰和一种开黄花的灌木。爬到山脊，你看见新墨西哥州、墨西哥和德州，三块地方一眼收下。`,`The air is dry and cool: cactus, yucca, a shrub with yellow flowers. At the ridge you can see New Mexico, Mexico and Texas, three places in one glance.`,`O ar é seco e fresco: catos, iúcas, um arbusto de flores amarelas. Na crista vês o Novo México, o México e o Texas, três sítios de uma só vez.`)],t(`德州味 +2 · 肌肉的酸痛是诚实的`,`Texanness +2 · Your aching legs are honest`,`Texanidade +2 · As pernas doridas não mentem`)),
     pre:()=>{stat('tex',2);stat('charme',1)}}
   ]},
   {id:'tx4_mission', n:t(`传教区小径`,`Mission Trail`,`Trilho das Missões`), acts:[
    {id:'walk', n:t(`走三座老教堂`,`Visit the three old churches`,`Visitar as três igrejas antigas`), cost:2, tip:t(`伊斯莱塔、索科罗、圣埃利萨里奥`,`Ysleta, Socorro, San Elizario`,`Ysleta, Socorro, San Elizario`),
     run:()=>({title:t(`传教区小径`,`Mission Trail`,`Trilho das Missões`),meta:t(`格兰德河谷 · 三百多年`,`Rio Grande valley · over three centuries`,`Vale do Rio Grande · mais de três séculos`),
      text:[t(`沿着河谷往东南，三座土坯教堂隔着几英里排成一线。伊斯莱塔教堂旁边住着提瓜族人，他们 1680 年代从新墨西哥一路南迁到这里，比德州这个名字还早。索科罗教堂的木梁是老的，屋顶被大水冲塌过，又被一代代人修起来。`,`Following the valley south-east, three adobe churches stand in a line a few miles apart. Beside the Ysleta mission live the Tigua people, who came south from New Mexico in the 1680s — before there was any such thing as Texas. The beams at Socorro are old; floods brought the roof down and generation after generation put it back.`,`Seguindo o vale para sudeste, três igrejas de adobe alinham-se a poucas milhas umas das outras. Junto à missão de Ysleta vive o povo tigua, que desceu do Novo México na década de 1680 — antes de existir sequer o Texas. As vigas de Socorro são antigas; as cheias deitaram o telhado abaixo e geração após geração voltou a pô-lo.`)],
      choices:[
       {t:t(`为若泽点一支蜡烛`,`Light a candle for José`,`Acender uma vela pelo José`),fx:()=>{stat('saud',-2);if(met('albertina'))addLike('albertina',0.5)},next:()=>say(t(`蜡烛`,`A candle`,`Uma vela`),t(`你不太会祈祷，就只是站着。蜡烛的火苗往一边歪，像在听什么人说话。回去你要告诉阿尔贝蒂娜太太，她会说若泽一定收到了。`,`You're not much good at praying, so you just stand there. The flame leans to one side as if listening to someone. You'll tell Dona Albertina when you get back; she'll say José got the message.`,`Não tens grande jeito para rezar, por isso ficas só ali. A chama inclina-se para um lado, como se ouvisse alguém. Vais contar à Dona Albertina quando voltares; ela vai dizer que o José recebeu o recado.`),t(`乡愁 −2`,`Homesickness −2`,`Saudade −2`))},
]})},
    {id:'maricela', n:t(`找玛丽塞拉`,`Find Maricela`,`Procurar a Maricela`), cost:2, req:arcReq('maricela','elpaso'), tip:t(`历史老师，两岸都有家`,`A history teacher with family on both banks`,`Uma professora de História com família nas duas margens`), run:marScene}
   ]},
   {id:'tx4_downtown', n:t(`市中心与圣哈辛托广场`,`Downtown & San Jacinto Plaza`,`Baixa e Praça San Jacinto`), acts:[
    {id:'plaza', n:t(`在广场摆快闪摊`,`Pop-up stall on the plaza`,`Banca improvisada na praça`), cost:3, req:ONCE('epplaza'), tip:t(`太阳碗那几周人最多`,`Busiest in Sun Bowl weeks`,`Mais gente nas semanas do Sun Bowl`),
     run:()=>{mark('epplaza');const r=popupSell(sunBowl()?18:12,sunBowl()?1.4:1.1);S.rep+=1;
      return say(t(`圣哈辛托广场`,`San Jacinto Plaza`,`Praça San Jacinto`),[t(`广场中间有一组鳄鱼雕塑。老人们告诉你，很多年前这里的水池里真的养过活鳄鱼，后来鳄鱼被搬走，雕塑留了下来。`,`In the middle of the plaza is a sculpture of alligators. The old-timers tell you that for decades real alligators lived in a pond here; the alligators were moved out, the sculpture stayed.`,`No meio da praça há uma escultura de jacarés. Os mais velhos contam-te que durante décadas viveram ali jacarés verdadeiros num lago; os jacarés foram levados, a escultura ficou.`),sunBowl()?t(`太阳碗那几周，球迷穿着两队的颜色挤满了街，烤肉的烟一飘过去就有人排队。`,`It's Sun Bowl week; fans in both teams' colours pack the streets, and the moment your smoke drifts over a line forms.`,`É semana do Sun Bowl; adeptos com as cores das duas equipas enchem as ruas e, mal o fumo chega lá, forma-se uma fila.`):t(`午休的上班族、穿制服的士兵、推婴儿车的母亲。有人问你“这是什么墨西哥菜”，你解释了三遍，最后说“就当是吧”。`,`Office workers on lunch, soldiers in uniform, mothers with strollers. Someone asks what kind of Mexican food this is. You explain three times, then say, "Sure, close enough."`,`Gente dos escritórios na hora de almoço, soldados fardados, mães com carrinhos. Alguém pergunta que tipo de comida mexicana é esta. Explicas três vezes e acabas por dizer: «Pronto, quase.»`),sellLine(r)],t(`快闪摊 · 口碑 +1`,`Pop-up · Reputation +1`,`Banca · Reputação +1`))}},
    {id:'market', n:t(`逛边境批发市场`,`Border wholesale market`,`Mercado grossista da fronteira`), cost:2, req:ONCE('epmkt'), tip:t(`面粉、鸡蛋、奶酪，还有便宜猪肉`,`Flour, eggs, cheese — and cheap pork`,`Farinha, ovos, queijo — e porco barato`),
     run:()=>{mark('epmkt');return {title:t(`批发市场`,`The wholesale market`,`O mercado grossista`),meta:t(`经营 · 采购`,`Business · buying`,`Negócio · compras`),
      text:[t(`靠近大桥的几条街全是批发铺子，货车从对岸过来卸货，讨价还价一半英语一半西班牙语。面粉一袋一袋码到天花板，奶酪论块卖，猪肉的价钱比奥斯汀低一截。`,`The streets near the bridge are all wholesalers; trucks come over from the other side to unload and the haggling is half English, half Spanish. Flour sacks are stacked to the ceiling, cheese sold by the block, and pork goes for a good deal less than in Austin.`,`As ruas perto da ponte são só armazenistas; os camiões chegam do outro lado para descarregar e o regateio é meio inglês, meio espanhol. Sacos de farinha empilhados até ao teto, queijo vendido ao bloco, e o porco muito mais barato do que em Austin.`)],
      choices:[
       {t:t(`买 30 份面粉蛋奶（五五折）`,`Buy 30 units of flour, eggs & milk (55%)`,`Comprar 30 unidades de farinha, ovos e leite (55%)`),fx:()=>{S.flags.tx4_epc=cityBuy('dairy',30,0.55)},next:()=>say(t(`装车`,`Loading up`,`Carregar`),buyLine(S.flags.tx4_epc,30,ING.dairy.n))},
       {t:t(`买 15 份猪肉（七五折）`,`Buy 15 units of pork (75%)`,`Comprar 15 unidades de porco (75%)`),fx:()=>{S.flags.tx4_epc=cityBuy('pork',15,0.75)},next:()=>say(t(`装车`,`Loading up`,`Carregar`),buyLine(S.flags.tx4_epc,15,ING.pork.n))},
       {t:t(`只看不买`,`Just look`,`Só ver`)}]}}},
    {id:'bliss', n:t(`布利斯堡军属家庭日`,`Fort Bliss family day cookout`,`Churrasco do dia da família em Fort Bliss`), cost:3, req:()=>S.flags.tx4_bliss===S.week?t(`这周已经去过了`,`Already done this week`,`Já foste esta semana`):true, tip:t(`陆军大基地，给士兵家属烤肉`,`A huge Army post — grill for soldiers' families`,`Uma grande base do Exército — grelhar para as famílias dos soldados`),
     run:()=>{S.flags.tx4_bliss=S.week;const r=popupSell(16,1.2);S.rep+=2;stat('tex',2);if(met('earl'))addTrust('earl',1);
      return say(t(`布利斯堡`,`Fort Bliss`,`Fort Bliss`),[t(`布利斯堡是全美最大的陆军基地之一，从城北一直延伸进新墨西哥的沙漠。家庭日的草坪上，刚从海外回来的士兵抱着孩子转圈，一个中士吃完你的猪排包，问能不能把饼皮的做法写给他老婆。`,`Fort Bliss is one of the largest Army posts in the country, stretching from the north of the city into the New Mexico desert. On the family-day lawn soldiers just back from overseas swing their kids in circles, and a sergeant who has just finished your pork sandwich asks if you'll write the bread recipe down for his wife.`,`Fort Bliss é uma das maiores bases do Exército do país e estende-se do norte da cidade até ao deserto do Novo México. No relvado do dia da família, soldados acabados de chegar do estrangeiro rodopiam com os filhos ao colo, e um sargento que acabou de comer a tua bifana pergunta se lhe escreves a receita do pão para a mulher.`),met('earl')?t(`你想起厄尔吧台后面那块褪色的部队臂章。回去要跟他说说这里。`,`You think of the faded unit patch behind Earl's bar. You'll tell him about this place.`,`Lembras-te do emblema desbotado atrás do balcão do Earl. Vais contar-lhe deste sítio.`):t(`一个老兵说：“谢谢你，孩子。”你不知道为什么脸红了。`,`An old veteran says, "Thank you, son." You don't know why you blush.`,`Um veterano diz: «Obrigado, filho.» Não sabes porque coras.`),sellLine(r)],t(`口碑 +2 · 德州味 +2`,`Reputation +2 · Texanness +2`,`Reputação +2 · Texanidade +2`))}}
   ]}
  ]
 }
});

/* ================= BIG BEND & TERLINGUA ================= */
const cookoff=()=>inSeason(19,21), bloom=()=>inSeason(37,44);
const noraScene=()=>{const s=stg('nora'),C='bigbend',N='nora';
 if(s>=4)return hang(N,[
  [[t(`诺拉在游客中心门口抽烟，看见你，把烟掐了。“又来了？这片沙漠留不住人，可总有人回来。”她指给你看今晚哪颗星最亮。`,`Nora is smoking outside the visitor center; she stubs it out when she sees you. "Back again? This desert doesn't keep people, but some keep coming back." She shows you which star will be brightest tonight.`,`A Nora está a fumar à porta do centro de visitantes e apaga o cigarro quando te vê. «Outra vez? Este deserto não prende ninguém, mas há quem volte sempre.» Mostra-te qual vai ser a estrela mais brilhante esta noite.`)],()=>stat('saud',-2)],
  [[t(`她在修一块被熊抓坏的垃圾箱盖。你帮她拧了半小时螺丝，她请你喝了一罐温啤酒。“这就是公园里的工资。”`,`She's fixing a trash-bin lid a bear has clawed up. You help with the screws for half an hour; she pays you with a warm beer. "That's park wages."`,`Está a arranjar a tampa de um contentor que um urso estragou. Ajudas com os parafusos meia hora e ela paga-te com uma cerveja morna. «É o salário do parque.»`)],()=>stat('tex',1)]]);
 if(s===0)return {title:t(`奇索斯山盆地，傍晚讲座`,`Chisos Basin, evening talk`,`Bacia dos Chisos, palestra ao fim da tarde`),meta:metaArc(N),
  text:[t(`露天剧场的石凳上坐了二十来个游客。讲解的女护林员三十多岁，晒得很黑，帽檐压得很低。“奇索斯是全美唯一一整座都在国家公园里的山脉。这里有黑熊，有美洲狮，天黑以后会有你们一辈子没见过的星星。还有——”她停下来，看着你脚边那一小瓶水，“——还有每年都有人以为一瓶水就够。”`,`Twenty-odd visitors sit on the stone benches of the amphitheater. The ranger is in her thirties, sunburned dark, hat brim low. "The Chisos are the only mountain range in the country that lies entirely inside a national park. There are black bears here, mountain lions, and after dark you'll see stars like you've never seen in your lives. And—" she stops and looks at the little bottle of water by your feet "—and every year somebody thinks one bottle is enough."`,`Uns vinte visitantes sentados nos bancos de pedra do anfiteatro. A guarda tem trinta e tal anos, muito queimada do sol, a aba do chapéu em baixo. «Os Chisos são a única cordilheira do país que fica toda dentro de um parque nacional. Há ursos-negros, pumas e, depois de escurecer, vão ver estrelas como nunca viram na vida. E—» para e olha para a garrafinha de água aos teus pés «—e todos os anos há alguém que acha que uma garrafa chega.»`)],
  choices:[
   {t:t(`举手认错，问她该带多少`,`Own up and ask how much you should carry`,`Admitir e perguntar quanto devias levar`),fx:step(N,C,()=>{addTrust(N,2)}),next:()=>say(t(`诺拉·布莱克韦尔`,`Nora Blackwell`,`Nora Blackwell`),t(`“一个人一天一加仑。夏天加倍。”讲座散了，她递给你一个旧水壶：“诺拉·布莱克韦尔。下次来，还我。”`,`"A gallon a person a day. Double in summer." After the talk she hands you an old canteen. "Nora Blackwell. Bring it back next time."`,`«Um galão por pessoa por dia. No verão o dobro.» No fim dá-te um cantil velho. «Nora Blackwell. Devolve-mo da próxima vez.»`))},
   {t:t(`问她星星的事：你外公是靠星星打鱼的`,`Ask about the stars: your grandfather fished by them`,`Perguntar pelas estrelas: o teu avô pescava guiado por elas`),fx:step(N,C,()=>{addLike(N,2);stat('saud',2)}),next:()=>say(t(`诺拉·布莱克韦尔`,`Nora Blackwell`,`Nora Blackwell`),t(`她眼神变了。“渔夫？那你知道北极星。”她讲了半个钟头，散场后还站在停车场给你指猎户座。“我叫诺拉。这儿没人问星星，他们只问厕所在哪。”`,`Something in her face changes. "A fisherman? Then you know Polaris." She talks for half an hour and afterwards stands in the parking lot pointing out Orion. "I'm Nora. Nobody out here asks about the stars. They ask where the restrooms are."`,`Algo muda na cara dela. «Pescador? Então conheces a Estrela Polar.» Fala meia hora e no fim fica no parque de estacionamento a mostrar-te o Orionte. «Chamo-me Nora. Ninguém aqui pergunta pelas estrelas. Perguntam onde é a casa de banho.»`))},
]};
 if(s===1)return {title:t(`窗口小径，失踪的游客`,`Window Trail, an overdue hiker`,`Trilho da Janela, um caminhante atrasado`),meta:metaArc(N),
  text:[t(`你在小径口还水壶，诺拉的对讲机响了：一个独自下山的游客过了时间还没回来。“窗口那段是个大石缝，下去容易，上来要命。”她看看你：“你腿脚怎么样？”`,`You're returning the canteen at the trailhead when Nora's radio crackles: a solo hiker is overdue. "The Window is a big pour-off in the rock. Easy going down, murder coming up." She looks at you. "How are your legs?"`,`Estás a devolver o cantil no início do trilho quando o rádio da Nora estala: um caminhante sozinho está atrasado. «A Janela é uma grande fenda na rocha. Descer é fácil, subir é de morte.» Olha para ti. «Como estão as tuas pernas?»`)],
  choices:[
   {t:t(`背他上来`,`Carry him out`,`Trazê-lo às costas`),req:()=>S.muscle>=2||S.stats.tex>=40||NEED(t(`肌肉 2 或德州味 40`,`Muscle 2 or Texanness 40`,`Músculo 2 ou Texanidade 40`)),fx:step(N,C,()=>{addTrust(N,3);S.rep+=3;stat('tex',2)}),next:()=>say(t(`石缝`,`The pour-off`,`A fenda`),t(`他扭了脚踝，脱水，嘴唇发白。你背着他一步一步往上挪，诺拉在前面开路。到了停车场，她递给你一瓶电解质水：“你们葡萄牙人都这么倔吗？”当地报纸登了一小段，没写名字，只写了“一位葡萄牙厨师”。`,`He's twisted an ankle, dehydrated, lips white. You carry him up step by step while Nora clears the way. In the parking lot she hands you an electrolyte drink. "Are all you Portuguese this stubborn?" The local paper runs a short piece: no name, just "a Portuguese cook."`,`Torceu o tornozelo, está desidratado, os lábios brancos. Carregas com ele degrau a degrau enquanto a Nora abre caminho. No parque de estacionamento ela dá-te uma bebida isotónica. «Vocês, portugueses, são todos assim teimosos?» O jornal local publica uma notícia curta: sem nome, só «um cozinheiro português».`),t(`诺拉信任 +3 · 口碑 +3`,`Nora's trust +3 · Reputation +3`,`Confiança da Nora +3 · Reputação +3`))},
   {t:t(`把水全给他，陪他坐在阴影里等救援`,`Give him all your water and sit with him in the shade until help comes`,`Dar-lhe a água toda e ficar com ele à sombra até chegar ajuda`),fx:step(N,C,()=>{addLike(N,2);addTrust(N,1);stat('charme',1)}),next:()=>say(t(`阴影里`,`In the shade`,`À sombra`),t(`你讲了两个钟头里斯本的事，让他别睡着。救援队到的时候，他说他明年要去里斯本。诺拉在回程的车上说：“陪着人等，比冲上去难。”`,`You talk about Lisbon for two hours to keep him awake. When the rescue team arrives he says he's going to Lisbon next year. On the drive back Nora says, "Waiting with someone is harder than charging in."`,`Falas de Lisboa durante duas horas para ele não adormecer. Quando a equipa de resgate chega, ele diz que no próximo ano vai a Lisboa. No regresso, a Nora diz: «Esperar ao lado de alguém custa mais do que avançar.»`),t(`诺拉好感 +2 · 信任 +1`,`Nora's affection +2 · Trust +1`,`Afeto da Nora +2 · Confiança +1`))},
]};
 if(s===2)return {title:t(`特林瓜，门廊上的日落`,`Terlingua, sunset on the porch`,`Terlingua, pôr do sol no alpendre`),meta:metaArc(N),
  text:[t(`特林瓜以前是个水银矿镇，矿关了，人走了，只剩石头房子的空壳和一片插着木十字架的老墓地。傍晚，镇上的人都坐到老商店的长门廊上，看奇索斯山被夕阳染成粉紫色。诺拉在你旁边坐下，从包里拿出一张褪色的照片。`,`Terlingua was a mercury-mining town; the mines closed, the people left, and what remains are stone shells of houses and an old cemetery of wooden crosses. At dusk the whole town sits along the long porch of the old store to watch the Chisos turn pink and violet. Nora sits down beside you and takes a faded photo out of her bag.`,`Terlingua era uma vila de minas de mercúrio; as minas fecharam, as pessoas foram-se, e ficaram as cascas de pedra das casas e um cemitério antigo de cruzes de madeira. Ao fim da tarde a vila inteira senta-se no alpendre comprido da velha loja a ver os Chisos ficarem cor-de-rosa e violeta. A Nora senta-se ao teu lado e tira uma fotografia desbotada do saco.`),
   t(`“上次你说你舅舅姓什么，我就觉得耳熟。”照片上是圣埃伦娜峡谷口，一个黑发男人蹲在河边，手里举着一串烤鱼，笑得眼睛眯成线。若泽。“他每年十月来露营一个星期，在营地给管理员烤鱼。有一年他问我，这里的星星和里斯本的是不是同一批。我说是，只是晚到几个钟头。他说：‘那我妹妹现在看见的，我待会儿也能看见。’”`,`"Last time you said your uncle's name, it rang a bell." The photo shows the mouth of Santa Elena Canyon: a dark-haired man crouched by the river holding up a string of grilled fish, laughing so hard his eyes are slits. José. "He came every October and camped for a week, grilled fish for the campground hosts. One year he asked me whether these were the same stars as over Lisbon. I said yes, just a few hours later. He said, 'Then what my sister's seeing now, I'll see in a bit.'"`,`«Da última vez que disseste o apelido do teu tio, soou-me familiar.» A fotografia mostra a boca do desfiladeiro de Santa Elena: um homem de cabelo escuro de cócoras junto ao rio com uma fieira de peixe grelhado, a rir tanto que os olhos são dois riscos. O José. «Vinha todos os outubros acampar uma semana e grelhava peixe para os responsáveis do parque de campismo. Um ano perguntou-me se estas estrelas eram as mesmas de Lisboa. Eu disse que sim, só umas horas mais tarde. Ele disse: "Então o que a minha irmã está a ver agora, eu vejo daqui a bocado."»`)],
  choices:[
   {t:t(`把照片拍下来发给鲁伊，让他给母亲看`,`Photograph it and send it to Rui to show your mother`,`Fotografá-la e mandá-la ao Rui para mostrar à tua mãe`),fx:step(N,C,()=>{S.flags.tx4_josePhoto=1;addTrust(N,2);stat('saud',-3);log('诺拉给了你一张若泽的旧照片','Nora gave you an old photo of José','A Nora deu-te uma fotografia antiga do José')}),next:()=>say(t(`照片`,`The photo`,`A fotografia`),t(`半夜鲁伊回了消息：“妈看了很久。她说他还是那样笑。她说：‘他在看星星，那就好。’”诺拉把原件塞进你手里：“它本来就该是你们家的。”`,`Rui replies in the middle of the night: "Mum looked at it a long time. She says he still laughs the same. She said, 'If he was looking at the stars, then that's all right.'" Nora presses the original into your hand. "It was always your family's."`,`O Rui responde a meio da noite: «A mãe esteve muito tempo a olhar. Diz que ele continua a rir da mesma maneira. Disse: "Se ele olhava para as estrelas, então está bem."» A Nora mete-te o original na mão. «Sempre foi da tua família.»`),t(`得到：若泽的照片 · 乡愁 −3`,`Received: José's photo · Homesickness −3`,`Recebeste: a fotografia do José · Saudade −3`))},
   {t:t(`什么都不说，看到太阳完全落下`,`Say nothing; watch until the sun is fully down`,`Não dizer nada; ficar a ver até o sol se pôr de vez`),fx:step(N,C,()=>{S.flags.tx4_josePhoto=1;addLike(N,2);stat('saud',3)}),next:()=>say(t(`门廊`,`The porch`,`O alpendre`),t(`天黑了，门廊上有人弹起吉他。诺拉说：“我在这儿七年了。每个来这儿的人都在躲什么。你舅舅躲的是一片海。”她把照片留给了你。`,`It's dark; someone on the porch starts playing guitar. Nora says, "Seven years I've been out here. Everybody who comes is hiding from something. Your uncle was hiding from a sea." She leaves you the photo.`,`Escureceu; alguém no alpendre começa a tocar guitarra. A Nora diz: «Estou aqui há sete anos. Toda a gente que vem para cá está a fugir de alguma coisa. O teu tio fugia de um mar.» Deixa-te a fotografia.`),t(`得到：若泽的照片 · 乡愁 +3`,`Received: José's photo · Homesickness +3`,`Recebeste: a fotografia do José · Saudade +3`))}]};
 return {title:t(`暗夜星空`,`Dark sky`,`Céu escuro`),meta:metaArc(N),
  text:[t(`大本德是国际认证的暗夜公园，方圆几十英里没有一盏路灯。诺拉开车带你到河边一块空地，关掉车灯。银河从山顶一直垂到墨西哥那边。她递给你一个旧六分仪：“这是我爷爷的，他是海军。我不会用。你外公会。”`,`Big Bend is a certified International Dark Sky Park; there isn't a streetlight for dozens of miles. Nora drives you to a clearing by the river and kills the headlights. The Milky Way hangs from the peaks all the way down to the Mexican side. She hands you an old sextant. "My grandpa's. Navy. I never learned it. Your grandfather would have."`,`Big Bend é um Parque Internacional de Céu Escuro certificado; não há um candeeiro em dezenas de milhas. A Nora leva-te até uma clareira junto ao rio e apaga os faróis. A Via Láctea pende dos cumes até ao lado mexicano. Dá-te um sextante velho. «Era do meu avô. Marinha. Nunca aprendi. O teu avô saberia.»`)],
  choices:[
   {t:t(`讲出“圣安东尼号”沉船的真相`,`Tell her the truth about the wreck of the Santo António`,`Contar-lhe a verdade sobre o naufrágio do Santo António`),req:()=>S.letters>=8||NEED(t(`读过第 8 封信`,`Have read letter 8`,`Ter lido a carta 8`)),fx:step(N,C,()=>{addTrust(N,3);S.rep+=5;S.online+=5;stat('saud',-8);stat('charme',2)}),next:()=>say(t(`六分仪`,`The sextant`,`O sextante`),[t(`你讲外公、风暴、那一晚若泽为了救人弃船。诺拉听完，把六分仪举起来对着北极星，手在抖。“那他每年来这儿看星星，是在替那条船认路。”`,`You tell her about your grandfather, the storm, how José abandoned ship that night to save the others. When you finish, Nora raises the sextant to Polaris, hands shaking. "So every year he came out here to look at the stars, he was finding the way home for that boat."`,`Contas-lhe do avô, da tempestade, de como o José abandonou o barco nessa noite para salvar os outros. Quando acabas, a Nora levanta o sextante para a Estrela Polar, com as mãos a tremer. «Então todos os anos que vinha cá ver as estrelas, estava a mostrar o caminho de casa àquele barco.»`),t(`第二年春天，公园的护林员们开始组团去圣鲁伊斯吃烤鱼。诺拉在他们的内部通讯上写了一段：“35 号州际公路边，有一家店的老板会用星星认路。”`,`The next spring the park rangers start making group trips to San Luís for grilled fish. Nora writes a paragraph in their staff newsletter: "On I-35 there's a shop whose owner can find his way by the stars."`,`Na primavera seguinte os guardas do parque começam a fazer excursões a San Luís para comer peixe grelhado. A Nora escreve um parágrafo no boletim interno: «Na I-35 há um restaurante cujo dono sabe orientar-se pelas estrelas.»`)],t(`口碑 +5 · 线上评分 +5 · 乡愁 −8 · 诺拉的故事完结`,`Reputation +5 · Online +5 · Homesickness −8 · Nora's story complete`,`Reputação +5 · Online +5 · Saudade −8 · História da Nora concluída`))},
   {t:t(`让她教你用六分仪`,`Have her teach you the sextant`,`Pedir-lhe que te ensine o sextante`),fx:step(N,C,()=>{addLike(N,2);S.rep+=4;S.online+=4;stat('saud',-5);stat('oficio',2)}),next:()=>say(t(`六分仪`,`The sextant`,`O sextante`),[t(`你们俩都不会，一起照着手机上的说明折腾到半夜，算出来的纬度差了三百英里。诺拉笑得躺在引擎盖上。“够了，”她说，“迷路的人不需要准，只需要有人陪着算。”`,`Neither of you knows how; you fumble through the instructions on your phone until midnight and your latitude comes out three hundred miles off. Nora laughs so hard she lies back on the hood. "That's enough," she says. "Lost people don't need precision. They need someone doing the sums with them."`,`Nenhum dos dois sabe; andam às voltas com as instruções no telemóvel até à meia-noite e a latitude sai trezentas milhas ao lado. A Nora ri tanto que se deita no capô. «Chega», diz ela. «Quem está perdido não precisa de rigor. Precisa de alguém que faça as contas com ele.»`),t(`之后护林员们开始组团去圣鲁伊斯吃饭，说是“诺拉推荐的”。`,`After that the rangers start road-tripping to San Luís to eat, "because Nora said so."`,`Depois disso os guardas começam a ir a San Luís comer, «porque a Nora disse».`)],t(`口碑 +4 · 线上评分 +4 · 乡愁 −5 · 诺拉的故事完结`,`Reputation +4 · Online +4 · Homesickness −5 · Nora's story complete`,`Reputação +4 · Online +4 · Saudade −5 · História da Nora concluída`))}]};
};
Object.assign(CITIES,{
 bigbend:{
  n:t(`大本德与特林瓜`,`Big Bend & Terlingua`,`Big Bend e Terlingua`), region:'west', miles:470, trip:'overnight', hotel:120,
  desc:t(`格兰德河在这里拐一个大弯。沙漠、峡谷、一座整个装在国家公园里的山，还有一个只剩墓地热闹的鬼镇。`,`Here the Rio Grande makes its big bend: desert, canyons, a mountain range wholly inside a national park, and a ghost town whose liveliest place is the cemetery.`,`Aqui o Rio Grande faz a sua grande curva: deserto, desfiladeiros, uma serra inteira dentro de um parque nacional e uma vila-fantasma cujo sítio mais animado é o cemitério.`),
  arrive:()=>{const v=S.visited.bigbend||0;
   if(v<=1)return [t(`过了马拉松镇就再没有手机信号。路一直往南，一百英里只看见两辆车和一只走鹃。你第一次明白“地广人稀”不是形容词，是警告。`,`Past the town of Marathon the phone signal dies. The road runs south; in a hundred miles you see two cars and one roadrunner. For the first time you understand that "wide open spaces" isn't a description. It's a warning.`,`Depois da vila de Marathon acaba o sinal do telemóvel. A estrada vai para sul; em cem milhas vês dois carros e um papa-léguas. Pela primeira vez percebes que «espaços abertos» não é uma descrição. É um aviso.`)];
   return [bloom()?t(`路两边开满了大本德特有的高个子蓝帽花，比奥斯汀那边的高一倍。`,`Both sides of the road are covered in Big Bend's own tall bluebonnets, twice the height of the ones around Austin.`,`As bermas estão cobertas dos tremoços-azuis próprios de Big Bend, com o dobro da altura dos de Austin.`):t(`信号又没了。你已经习惯了，甚至有点期待。`,`The signal's gone again. You're used to it by now — you almost look forward to it.`,`O sinal desapareceu outra vez. Já te habituaste — quase esperas por isso.`)]},
  locs:[
   {id:'tx4_chisos', n:t(`奇索斯山`,`Chisos Mountains`,`Montanhas Chisos`), acts:[
    {id:'window', n:t(`走窗口小径`,`Hike the Window Trail`,`Fazer o trilho da Janela`), cost:3, req:DAY, tip:t(`穿过山谷，走到一个对着沙漠的石缝`,`Through the basin to a rock notch over the desert`,`Pela bacia até uma fenda na rocha sobre o deserto`),
     run:()=>{stat('tex',2);stat('saud',-1);return say(t(`窗口小径`,`Window Trail`,`Trilho da Janela`),[t(`小径一路往下，两边是橡树和杜松。走到尽头，两块巨石夹出一个缺口，雨水从这里冲下去，落进几百米下的沙漠。缺口外的世界是粉色和灰色的，一直铺到墨西哥。`,`The trail drops steadily between oaks and junipers. At the end two great rocks pinch together into a notch where rainwater pours off into the desert hundreds of metres below. Beyond the notch the world is pink and grey, all the way to Mexico.`,`O trilho desce sempre entre carvalhos e zimbros. No fim, duas rochas enormes apertam-se numa fenda por onde a água da chuva cai para o deserto centenas de metros abaixo. Para lá da fenda o mundo é rosa e cinzento, até ao México.`),inSeason(1,12)?t(`回程全是上坡，正午四十度。你把诺拉说的一加仑喝得一滴不剩。`,`The way back is all uphill at forty degrees in the midday sun. You drink every drop of the gallon.`,`O regresso é sempre a subir, quarenta graus ao meio-dia. Bebes o galão até à última gota.`):t(`回程有一头黑熊在远处的坡上吃仙人掌果，完全不理你。`,`On the way back a black bear on a far slope is eating prickly-pear fruit and ignoring you completely.`,`No regresso, um urso-negro numa encosta ao longe está a comer figos-da-índia e ignora-te por completo.`)],t(`德州味 +2 · 乡愁 −1`,`Texanness +2 · Homesickness −1`,`Texanidade +2 · Saudade −1`))}},
    {id:'nora', n:t(`找护林员诺拉`,`Find Ranger Nora`,`Procurar a guarda Nora`), cost:2, req:arcReq('nora','bigbend'), tip:t(`游客中心、营地、夜里的星空讲座`,`Visitor center, campground, night-sky talks`,`Centro de visitantes, parque de campismo, palestras sobre o céu`), run:noraScene}
   ]},
   {id:'tx4_santaelena', n:t(`圣埃伦娜峡谷`,`Santa Elena Canyon`,`Desfiladeiro de Santa Elena`), acts:[
    {id:'canyon', n:t(`走进峡谷口`,`Walk into the canyon mouth`,`Entrar na boca do desfiladeiro`), cost:2, tip:t(`峭壁一边是德州，一边是墨西哥`,`One cliff is Texas, the other Mexico`,`Uma falésia é o Texas, a outra o México`),
     run:()=>({title:t(`圣埃伦娜峡谷`,`Santa Elena Canyon`,`Desfiladeiro de Santa Elena`),meta:t(`格兰德河`,`Rio Grande`,`Rio Grande`),
      text:[t(`河水从两面四百多米高的峭壁之间流出来。左边那面墙是美国，右边那面是墨西哥，中间的河宽得一块石头就能扔过去。你小时候以为国界是画在地图上的，原来有的国界是一条河自己切出来的。`,`The river slides out between two cliffs more than four hundred metres high. The wall on the left is the United States, the wall on the right is Mexico, and the river between them is a stone's throw wide. As a boy you thought borders were drawn on maps; it turns out some are cut by a river on its own.`,`O rio sai entre duas falésias com mais de quatrocentos metros de altura. A parede da esquerda são os Estados Unidos, a da direita é o México, e o rio entre as duas tem a largura de uma pedrada. Em miúdo achavas que as fronteiras se desenhavam nos mapas; afinal há algumas que um rio cavou sozinho.`)],
      choices:[
       {t:t(`在河边坐着发呆`,`Sit by the river and stare`,`Sentar-te junto ao rio a olhar`),fx:()=>{stat('saud',-3)},next:()=>say(t(`河边`,`By the river`,`Junto ao rio`),t(`一只蓝鹭站在浅水里，一动不动。你突然想起特茹河口的鹭，它们也是这样等鱼，等一辈子。`,`A blue heron stands motionless in the shallows. You remember the herons at the mouth of the Tagus; they wait for fish like this too, a whole lifetime.`,`Uma garça-azul está imóvel na água rasa. Lembras-te das garças na foz do Tejo; também esperam assim pelo peixe, uma vida inteira.`),t(`乡愁 −3`,`Homesickness −3`,`Saudade −3`))},
       {t:t(`让${WN()}站在峭壁下，拍一张`,`Get ${WN()} to stand under the cliff for a photo`,`Pôr ${WN()} debaixo da falésia para uma fotografia`),req:NEEDW,fx:()=>{if(W()){addLike(W(),1)}S.online+=2},next:()=>say(t(`照片`,`The photo`,`A fotografia`),t(`照片里${WN()}小得像一粒沙。“我看起来好渺小，”${WN()}说。你说：“你本来就很渺小，我也是。”你们俩都笑了。`,`In the photo ${WN()} is the size of a grain of sand. "I look so tiny," says ${WN()}. "You are tiny," you say. "So am I." You both laugh.`,`Na fotografia ${WN()} é do tamanho de um grão de areia. «Pareço tão pequenino», diz ${WN()}. «E és», dizes tu. «Eu também.» Riem-se os dois.`),t(`好感 +1 · 线上评分 +2`,`Affection +1 · Online +2`,`Afeto +1 · Online +2`))}]})}
   ]},
   {id:'tx4_terlingua', n:t(`特林瓜鬼镇`,`Terlingua Ghost Town`,`Vila-fantasma de Terlingua`), acts:[
    {id:'chili', n:t(`特林瓜辣肉酱大赛`,`Terlingua chili cook-off`,`Concurso de chili de Terlingua`), cost:3, req:()=>!cookoff()?t(`只在第 19–21 周（十一月初）`,`Weeks 19–21 only (early November)`,`Só nas semanas 19–21 (início de novembro)`):S.flags.tx4_chili?t(`今年已经比过了`,`Already competed this year`,`Já competiste este ano`):true, tip:t(`1967 年开始的老比赛，全国的辣酱迷都来`,`An old contest since 1967; chili-heads come from all over`,`Um concurso antigo, desde 1967; vêm fanáticos do chili de todo o lado`),
     run:()=>({title:t(`辣肉酱大赛`,`The chili cook-off`,`O concurso de chili`),meta:t(`经营 · 比赛`,`Business · contest`,`Negócio · concurso`),
      text:[t(`沙漠里搭起一片帐篷，几百口锅同时冒烟。德州的规矩：正宗辣肉酱里不能放豆子，谁放谁被赶出去。一个戴牛仔帽的老裁判警告你：“葡萄牙小子，你要是往锅里放鳕鱼，我亲自把你埋进那片墓地。”`,`A camp of tents goes up in the desert and hundreds of pots smoke at once. Texas rule: real chili has no beans in it, and anyone who adds them gets run off. An old judge in a cowboy hat warns you, "Portuguese boy, you put salt cod in that pot and I'll bury you in that cemetery myself."`,`Ergue-se um acampamento de tendas no deserto e centenas de panelas fumegam ao mesmo tempo. Regra do Texas: o verdadeiro chili não leva feijão, e quem o puser é corrido. Um velho jurado de chapéu de cowboy avisa-te: «Rapaz português, se puseres bacalhau nessa panela enterro-te eu naquele cemitério.»`)],
      choices:[
       {t:t(`报名，用葡式红椒酱和炭火慢炖`,`Enter with Portuguese red-pepper paste and a slow charcoal simmer`,`Inscrever-te com massa de pimentão e fogo lento de carvão`),req:MONEY(30),fx:()=>{S.cash-=30;S.flags.tx4_chili=1},next:()=>cityGrill(q=>{const pr=q>=1.3?600:q>=1.1?250:q>=0.9?80:0;S.cash+=pr;S.wk.rev+=pr;S.rep+=pr?4:1;S.online+=pr?5:1;stat('tex',3);
         return say(t(`评审结果`,`The judges' verdict`,`O veredicto do júri`),[pr>=600?t(`你拿了“最佳新人”和总分第二。老裁判说：“我收回墓地那句话。”`,`You take Best Newcomer and second place overall. The old judge says, "I take back what I said about the cemetery."`,`Ganhas o prémio de Melhor Estreante e o segundo lugar geral. O velho jurado diz: «Retiro o que disse do cemitério.»`):pr?t(`前二十名。一个从俄克拉何马来的老头要了你的方子，说要回去“偷偷用”。`,`Top twenty. An old man from Oklahoma asks for your recipe and says he'll "use it on the sly" back home.`,`Entre os vinte primeiros. Um velhote do Oklahoma pede-te a receita e diz que a vai «usar às escondidas» lá em casa.`):t(`没进名次，但你的锅是全场最先被吃光的。`,`No placing, but yours is the first pot in the whole camp to be emptied.`,`Não ficas classificado, mas a tua panela é a primeira do acampamento a ficar vazia.`),pr?t(`奖金 $${pr}`,`Prize $${pr}`,`Prémio $${pr}`):t(`没有奖金`,`No prize money`,`Sem prémio`)],t(`德州味 +3`,`Texanness +3`,`Texanidade +3`))})},
       {t:t(`不参赛，在帐篷之间摆摊`,`Don't compete — set up a stall between the tents`,`Não competir — montar uma banca entre as tendas`),fx:()=>{S.flags.tx4_chili=1;S.flags.tx4_cr=popupSell(20,1.35)},next:()=>say(t(`帐篷之间`,`Between the tents`,`Entre as tendas`),[t(`吃辣肉酱吃到第三锅的人，最想要的是一块不辣的烤猪肉。`,`People on their third pot of chili want nothing more than a piece of grilled pork that isn't hot.`,`Quem já vai na terceira panela de chili só quer um pedaço de porco grelhado que não pique.`),sellLine(S.flags.tx4_cr)])}]})},
    {id:'guides', n:t(`给河道向导们做饭`,`Cook for the river guides`,`Cozinhar para os guias do rio`), cost:2, req:ONCE('bbguide'), tip:t(`他们一整季都吃罐头`,`They live on canned food all season`,`Passam a temporada a comer enlatados`),
     run:()=>{mark('bbguide');const r=popupSell(10,1.5);S.online+=1;return say(t(`向导营地`,`Guides' camp`,`Acampamento dos guias`),[t(`十几个晒得像皮革的年轻人，刚从峡谷里划完三天的船。他们付钱很爽快，吃得一点不剩，还要你明年再来。`,`A dozen young people tanned like leather, just off three days of paddling the canyons. They pay without fuss, leave nothing on the plates, and make you promise to come back next season.`,`Uma dúzia de jovens curtidos como couro, acabados de remar três dias pelos desfiladeiros. Pagam sem discutir, não deixam nada no prato e fazem-te prometer que voltas na próxima temporada.`),sellLine(r)],t(`快闪摊 · 一点五倍价`,`Pop-up · 1.5× prices`,`Banca · preços a 1,5×`))}}
   ]},
   {id:'tx4_sky', n:t(`暗夜星空`,`The dark sky`,`O céu escuro`), acts:[
    {id:'stars', n:t(`躺在沙漠里看星星`,`Lie in the desert and watch the stars`,`Deitar-te no deserto a ver as estrelas`), cost:1, req:NIGHT, tip:t(`全美最暗的夜空之一`,`One of the darkest skies in the country`,`Um dos céus mais escuros do país`),
     run:()=>{stat('saud',-4);stat('charme',1);if(W())addLike(W(),1);return say(t(`星空`,`Stars`,`Estrelas`),[t(`星多得吓人，银河亮得在地上投出你的影子。你认出了猎户座和北斗，剩下的都叫不出名字。外公说过，海上的人看见这样的夜，就知道明天风平浪静。`,`So many stars it's frightening; the Milky Way is bright enough to cast your shadow on the ground. You recognise Orion and the Big Dipper; the rest have no names you know. Your grandfather used to say that when men at sea see a night like this, they know tomorrow will be calm.`,`Tantas estrelas que até assusta; a Via Láctea é tão clara que te faz sombra no chão. Reconheces o Orionte e a Ursa Maior; as outras não sabes como se chamam. O teu avô dizia que, quando os homens do mar veem uma noite assim, sabem que amanhã está calmo.`),...(W()?[t(`${WN()}躺在你旁边，好半天才说：“我在德州活了一辈子，从来不知道天上有这么多东西。”`,`${WN()} lies beside you and after a long while says, "Lived in Texas my whole life and never knew there was this much up there."`,`${WN()} está deitado ao teu lado e, passado muito tempo, diz: «Vivi a vida toda no Texas e nunca soube que havia tanta coisa lá em cima.»`)]:[])],t(`乡愁 −4 · 魅力 +1`,`Homesickness −4 · Charm +1`,`Saudade −4 · Charme +1`))}}
   ]}
  ]
 }
});

/* ================= LUBBOCK ================= */
const gameDay=()=>inSeason(13,24), harvest=()=>inSeason(15,24);
const wesScene=()=>{const s=stg('wes'),C='lubbock',K='wes';
 if(s>=4)return hang(K,[
  [[t(`韦斯在雕像下弹新歌，看见你就换成了你们那首。路过的两个女生跟着哼。“它现在是我的招牌了，”他说，“版税算你一半——等有了版税的话。”`,`Wes is playing something new under the statue; when he sees you he switches to your song. Two passing students hum along. "It's my signature now," he says. "Half the royalties are yours — once there are royalties."`,`O Wes está a tocar uma canção nova debaixo da estátua; quando te vê, passa para a vossa. Duas estudantes que passam trauteiam. «Agora é a minha imagem de marca», diz ele. «Metade dos direitos é tua — quando houver direitos.»`)],()=>stat('charme',1)],
  [[t(`他拉你去吃宵夜，问了一晚上里斯本的酒馆。“毕业我就去，”他说，“你得给我写地址。”`,`He drags you out for a late bite and asks about Lisbon taverns all night. "I'm going when I graduate," he says. "You'll write me the addresses."`,`Arrasta-te para comer qualquer coisa tarde e passa a noite a perguntar pelas tascas de Lisboa. «Vou quando acabar o curso», diz. «Tens de me escrever as moradas.»`)],()=>stat('saud',-2)]]);
 if(s===0)return {title:t(`巴迪·霍利雕像下`,`Under the Buddy Holly statue`,`Debaixo da estátua do Buddy Holly`),meta:metaArc(K),
  text:[t(`巴迪·霍利 1936 年生在拉伯克，二十二岁就死了，留下的歌改变了摇滚乐。他的铜像戴着那副标志性的黑框眼镜，脚下是西德州名人步道。雕像下一个瘦高的男生在弹《佩吉·苏》，弹成了小调，慢得像哀歌。他抬头看见你在听：“太丧了？我想写一种又悲伤又能跳舞的歌，可是找不到。”`,`Buddy Holly was born in Lubbock in 1936 and dead at twenty-two, and the songs he left changed rock and roll. His bronze statue wears the famous black-framed glasses, and at its feet runs the West Texas Walk of Fame. Under the statue a tall, skinny student is playing "Peggy Sue" in a minor key, slow as a lament. He looks up and sees you listening. "Too sad? I'm trying to write something sad you can still dance to. Can't find it."`,`O Buddy Holly nasceu em Lubbock em 1936 e morreu aos vinte e dois, e as canções que deixou mudaram o rock. A estátua de bronze usa os famosos óculos de massa preta e aos seus pés corre o Passeio da Fama do Oeste do Texas. Debaixo da estátua, um estudante alto e magro toca «Peggy Sue» em tom menor, lenta como um lamento. Levanta os olhos e vê-te a ouvir. «Triste demais? Quero escrever uma coisa triste que ainda se possa dançar. Não encontro.»`)],
  choices:[
   {t:t(`哼一段法多给他听`,`Hum him a bit of fado`,`Trautear-lhe um bocado de fado`),fx:step(K,C,()=>{addLike(K,2);stat('saud',2)}),next:()=>say(t(`韦斯·塔特姆`,`Wes Tatum`,`Wes Tatum`),t(`他听着，手指已经在琴颈上找和弦。“就是这个。这叫什么？”你说法多，“乡愁”的意思。“韦斯·塔特姆，德州理工，作曲专业，”他说，“下次你来，我们把它写出来。”`,`He listens, fingers already hunting chords on the neck. "That's it. What's it called?" Fado, you say; it's about homesickness. "Wes Tatum. Texas Tech, songwriting," he says. "Next time you're up here, we write it."`,`Ele ouve, com os dedos já à procura dos acordes. «É isto. Como se chama?» Fado, dizes; é sobre a saudade. «Wes Tatum. Texas Tech, composição», diz ele. «Da próxima vez que cá vieres, escrevemos isto.»`))},
   {t:t(`借他的吉他，弹一首凯尔乐队的“孤星法多”`,`Borrow his guitar and play a Lone Star Fado number from Kyle's band`,`Pedir-lhe a guitarra e tocar um tema Lone Star Fado da banda do Kyle`),req:()=>(S.flags.bandDebut&&S.flags.bandDebut!=='face')||NEED(t(`凯尔乐队首演时真唱过`,`Have really sung at Kyle's band debut`,`Ter cantado a sério na estreia da banda do Kyle`)),fx:step(K,C,()=>{addLike(K,2);addTrust(K,1);if(met('kyle'))addLike('kyle',1)}),next:()=>say(t(`韦斯·塔特姆`,`Wes Tatum`,`Wes Tatum`),t(`弹完他一把抓住你：“你有乐队？在圣鲁伊斯？我要见他们。”他叫韦斯，说下次你来之前，他先把歌词写好。`,`When you finish he grabs your arm. "You've got a band? In San Luís? I've gotta meet them." He's called Wes, and he says he'll have lyrics ready by your next visit.`,`Quando acabas agarra-te o braço. «Tens uma banda? Em San Luís? Tenho de os conhecer.» Chama-se Wes e diz que até à tua próxima visita tem a letra pronta.`))},
]};
 if(s===1)return {title:t(`德州理工，威尔·罗杰斯铜像下`,`Texas Tech, under the Will Rogers statue`,`Texas Tech, debaixo da estátua de Will Rogers`),meta:metaArc(K),
  text:[t(`校园是西班牙文艺复兴式的红瓦房子。韦斯坐在威尔·罗杰斯骑马的铜像下，本子上写满了划掉的句子。“副歌有了，桥段没有。我需要一句葡萄牙话，一句真的话。你在德州最想说却没说出口的是什么？”`,`The campus is red-tiled Spanish Renaissance buildings. Wes sits under the bronze of Will Rogers on his horse, his notebook full of crossed-out lines. "I've got the chorus. No bridge. I need one line in Portuguese — one true line. What's the thing you most want to say in Texas and haven't?"`,`O campus são edifícios de telha vermelha em estilo renascentista espanhol. O Wes está debaixo do bronze de Will Rogers a cavalo, com o caderno cheio de frases riscadas. «Tenho o refrão. Falta a ponte. Preciso de uma frase em português — uma frase verdadeira. O que é que mais queres dizer no Texas e ainda não disseste?»`)],
  choices:[
   {t:t(`“舅舅，你写了十二封信，一封都没寄。”`,`"Uncle, you wrote twelve letters and never sent one."`,`«Tio, escreveste doze cartas e não mandaste nenhuma.»`),fx:step(K,C,()=>{S.flags.tx4_wesSong='jose';addTrust(K,2);stat('saud',-2)}),next:()=>say(t(`桥段`,`The bridge`,`A ponte`),t(`韦斯把这句话抄下来，念了三遍，念得很烂，但很认真。“这首歌就叫《没寄出的信》。”`,`Wes copies it down and reads it back three times, badly but carefully. "Then the song's called 'Unsent Letters.'"`,`O Wes copia a frase e lê-a três vezes, mal mas com cuidado. «Então a canção chama-se "Cartas por mandar".»`))},
   {t:t(`“这里的天太大了，大得我想不起海。”`,`"The sky here's so big I can't remember the sea."`,`«Aqui o céu é tão grande que já não me lembro do mar.»`),fx:step(K,C,()=>{S.flags.tx4_wesSong='sky';addLike(K,2);stat('tex',2)}),next:()=>say(t(`桥段`,`The bridge`,`A ponte`),t(`“完美，”韦斯说，“每个拉伯克人都懂。我们这儿也没有海，只有棉花。”歌名定了：《大过海的天》。`,`"Perfect," Wes says. "Every soul in Lubbock gets that. We don't have a sea either. Just cotton." The title's settled: "Sky Bigger Than the Sea."`,`«Perfeito», diz o Wes. «Toda a gente em Lubbock percebe. Também não temos mar. Só algodão.» O título fica: «Um céu maior que o mar».`))},
   {t:t(`“我留在这儿，是因为一张纸，还是因为一个人？”`,`"Am I staying here because of a piece of paper, or because of someone?"`,`«Fico cá por causa de um papel ou por causa de alguém?»`),req:()=>met('ines')||!!S.settled||NEED(t(`心里有一个人`,`Someone on your mind`,`Alguém no pensamento`)),fx:step(K,C,()=>{S.flags.tx4_wesSong='love';addLike(K,1);addTrust(K,1);stat('charme',2)}),next:()=>say(t(`桥段`,`The bridge`,`A ponte`),t(`韦斯吹了声口哨：“兄弟，这是一首情歌。”他没问那个人是谁。歌名叫《纸与人》。`,`Wes whistles. "Brother, that's a love song." He doesn't ask who. The title: "Paper and People."`,`O Wes assobia. «Irmão, isso é uma canção de amor.» Não pergunta quem. O título: «Papel e pessoas».`))}]};
 if(s===2)return {title:t(`录小样`,`Cutting a demo`,`Gravar uma maqueta`),meta:metaArc(K),
  text:[t(`歌写完了，韦斯想录一版小样。“我缺一个会弹钢棒吉他的，还缺一个敢把法多唱成乡村的疯子。后一个是你。”`,`The song is finished and Wes wants to cut a demo. "I need somebody on steel guitar, and some lunatic willing to sing fado like it's country. That second one's you."`,`A canção está pronta e o Wes quer gravar uma maqueta. «Preciso de alguém na guitarra de aço e de um maluco capaz de cantar fado como se fosse country. Esse segundo és tu.»`)],
  choices:[
   {t:t(`打电话给凯尔，让他在电话里弹`,`Call Kyle and have him play down the line`,`Ligar ao Kyle e pô-lo a tocar ao telefone`),req:()=>met('kyle')||NEED(t(`认识凯尔`,`Know Kyle`,`Conhecer o Kyle`)),fx:step(K,C,()=>{S.flags.tx4_wesKyle=1;addLike('kyle',2);addTrust(K,1)}),next:()=>say(t(`三百英里的合奏`,`A jam three hundred miles long`,`Uma jam de trezentas milhas`),t(`凯尔在修理铺里接电话，把手机架在拖拉机上，抱起他那把旧钢棒吉他就弹。信号断了两次。录完，韦斯说：“这家伙得来拉伯克。”电话那头凯尔说：“这小子得来圣鲁伊斯。”`,`Kyle answers in the repair shop, props his phone on a tractor, grabs his old steel guitar and plays. The signal drops twice. When it's done Wes says, "That guy's gotta come to Lubbock." On the other end Kyle says, "That kid's gotta come to San Luís."`,`O Kyle atende na oficina, encosta o telemóvel a um trator, pega na velha guitarra de aço e toca. O sinal cai duas vezes. No fim o Wes diz: «Esse tipo tem de vir a Lubbock.» Do outro lado o Kyle diz: «Esse miúdo tem de vir a San Luís.»`),t(`凯尔好感 +2`,`Kyle's affection +2`,`Afeto do Kyle +2`))},
   {t:t(`出 $60 租学校的录音间`,`Pay $60 for a campus recording room`,`Pagar $60 por uma sala de gravação na universidade`),req:MONEY(60),fx:step(K,C,()=>{S.cash-=60;S.wk.spend+=60;addTrust(K,2);stat('oficio',1)}),next:()=>say(t(`录音间`,`The studio`,`O estúdio`),t(`隔音棉、一支好话筒、一个打瞌睡的助教。录了十一遍，第十一遍你唱破了音，韦斯说就用这一遍。`,`Foam on the walls, one good microphone, a teaching assistant dozing off. Eleven takes; on the eleventh your voice cracks and Wes says that's the one.`,`Espuma nas paredes, um bom microfone, um assistente a dormitar. Onze takes; no décimo primeiro a tua voz falha e o Wes diz que é esse.`))},
   {t:t(`傍晚去棉田边，用手机录`,`Go out to the cotton fields at dusk and record on a phone`,`Ir para os campos de algodão ao fim da tarde e gravar no telemóvel`),fx:step(K,C,()=>{addLike(K,2);stat('tex',2)}),next:()=>say(t(`棉田边`,`At the cotton fields`,`Junto ao algodão`),t(`风很大，录进去一半是风声。远处有一架风车在吱呀转。韦斯说这就是西德州的伴奏，花钱都买不来。`,`The wind is strong and half the recording is wind. Far off a windmill creaks round. Wes says that's West Texas backing, money can't buy it.`,`O vento é forte e metade da gravação é vento. Ao longe range um moinho. O Wes diz que é o acompanhamento do Oeste do Texas, nem com dinheiro se compra.`))}]};
 const song={jose:t(`《没寄出的信》`,`"Unsent Letters"`,`«Cartas por mandar»`),sky:t(`《大过海的天》`,`"Sky Bigger Than the Sea"`,`«Um céu maior que o mar»`),love:t(`《纸与人》`,`"Paper and People"`,`«Papel e pessoas»`)}[S.flags.tx4_wesSong]||t(`那首歌`,`the song`,`a canção`);
 return {title:t(`仓库区，开放麦之夜`,`Depot District, open-mic night`,`Depot District, noite de microfone aberto`),meta:metaArc(K),
  text:[t(`拉伯克的仓库区是一片老火车站边的砖房，晚上全是音乐。韦斯把${song}放上网的第二天，播放量过了五万。今晚他第一次在台上唱，点名要你上去唱葡语那段。`,`Lubbock's Depot District is a cluster of brick buildings by the old railway depot, full of music at night. The day after Wes put ${song} online it passed fifty thousand plays. Tonight he's singing it on stage for the first time and calls you up for the Portuguese part.`,`O Depot District de Lubbock é um conjunto de prédios de tijolo junto à velha estação de comboios, cheio de música à noite. No dia a seguir a o Wes pôr ${song} na internet passou as cinquenta mil reproduções. Hoje canta-a pela primeira vez em palco e chama-te para a parte em português.`),...(S.flags.tx4_wesKyle?[t(`简介里写着：“钢棒吉他：凯尔·布伦南，圣鲁伊斯。”凯尔已经截图发了三遍。`,`The credits read: "Steel guitar: Kyle Brennan, San Luís." Kyle has already sent the screenshot three times.`,`Nos créditos lê-se: «Guitarra de aço: Kyle Brennan, San Luís.» O Kyle já mandou a captura de ecrã três vezes.`)]:[])],
  choices:[
   {t:t(`上台唱，最后报上店名`,`Go up and sing, and name the shop at the end`,`Subir e cantar, e dizer o nome do restaurante no fim`),fx:step(K,C,()=>{S.online+=10;S.rep+=5;stat('charme',2);if(S.flags.tx4_wesKyle){addLike('kyle',2);addTrust('kyle',1)}if(met('earl'))addLike('earl',1);log('韦斯的歌走红：线上评分 +10','Wes\'s song takes off: Online +10','A canção do Wes dispara: Online +10')}),next:()=>say(t(`开放麦`,`Open mic`,`Microfone aberto`),[t(`唱完全场跺脚。你对着话筒说：“35 号州际公路，圣鲁伊斯，若泽烧烤店。”后来每个月都有德州理工的学生开三百英里来吃一顿，说是“歌里那家”。`,`When you finish the whole room stomps. Into the mic you say, "I-35, San Luís, Zé's Churrasco." After that, every month some Texas Tech students drive three hundred miles for a meal at "the place from the song."`,`Quando acabas a sala inteira bate os pés. Ao microfone dizes: «I-35, San Luís, Zé's Churrasco.» Desde então, todos os meses há estudantes da Texas Tech que fazem trezentas milhas para comer no «sítio da canção».`),met('earl')?t(`厄尔把这首歌加进了酒吧的点唱机，只是假装不知道是谁唱的。`,`Earl adds the song to the saloon jukebox and pretends not to know who's singing.`,`O Earl põe a canção na jukebox do bar e finge não saber quem canta.`):t(`你第一次觉得，口音也可以是一种乐器。`,`For the first time you feel an accent can be an instrument.`,`Pela primeira vez sentes que um sotaque pode ser um instrumento.`)],t(`线上评分 +10 · 口碑 +5 · 魅力 +2 · 韦斯的故事完结`,`Online +10 · Reputation +5 · Charm +2 · Wes's story complete`,`Online +10 · Reputação +5 · Charme +2 · História do Wes concluída`))},
   {t:t(`让韦斯一个人唱，你在台下听`,`Let Wes sing it alone; listen from the floor`,`Deixar o Wes cantar sozinho; ouvir cá de baixo`),fx:step(K,C,()=>{S.online+=6;S.rep+=3;addTrust(K,3);stat('saud',-3);if(S.flags.tx4_wesKyle)addLike('kyle',1)}),next:()=>say(t(`开放麦`,`Open mic`,`Microfone aberto`),t(`他唱葡语那句时发音全错，但台下没人在乎。唱完他指着你：“这首歌是他的。”掌声转向你，你只举了举啤酒。`,`He mangles every vowel of the Portuguese line and nobody cares. At the end he points at you. "This song's his." The applause swings your way; you just raise your beer.`,`Estraga todas as vogais da frase em português e ninguém quer saber. No fim aponta para ti. «Esta canção é dele.» Os aplausos viram-se para ti; só levantas a cerveja.`),t(`线上评分 +6 · 口碑 +3 · 韦斯的故事完结`,`Online +6 · Reputation +3 · Wes's story complete`,`Online +6 · Reputação +3 · História do Wes concluída`))}]};
};
Object.assign(CITIES,{
 lubbock:{
  n:t(`拉伯克`,`Lubbock`,`Lubbock`), region:'north', miles:300, trip:'overnight', hotel:85,
  desc:t(`南部大平原上的大学城，四面都是棉田。巴迪·霍利的故乡，风大到能把歌吹进你耳朵。`,`A college town on the South Plains, cotton fields in every direction. Buddy Holly's hometown, where the wind blows songs right into your ears.`,`Uma cidade universitária nas Planícies do Sul, com algodão para todos os lados. A terra do Buddy Holly, onde o vento te sopra canções para dentro dos ouvidos.`),
  arrive:()=>{const v=S.visited.lubbock||0;
   if(v<=1)return [t(`过了阿比林，地平得像一张桌子，路直得像尺子画的。你开了一个钟头，方向盘一下都没转。`,`Past Abilene the land goes flat as a table and the road runs as if drawn with a ruler. You drive an hour without turning the wheel once.`,`Depois de Abilene a terra fica plana como uma mesa e a estrada parece traçada a régua. Conduzes uma hora sem mexer no volante.`)];
   return [harvest()?t(`棉花收获季，路边堆着一个个卡车那么大的棉花包，风一吹，白絮飘得像下雪。`,`It's cotton harvest: modules the size of trucks line the roads, and when the wind blows the lint drifts like snow.`,`É a colheita do algodão: fardos do tamanho de camiões alinham-se nas bermas e, quando sopra o vento, os flocos voam como neve.`):t(`风还是那么大。你学会了下车先按住帽子。`,`The wind's as strong as ever. You've learned to hold your hat before you open the door.`,`O vento continua forte. Aprendeste a segurar o chapéu antes de abrir a porta.`)]},
  locs:[
   {id:'tx4_holly', n:t(`巴迪·霍利中心`,`Buddy Holly Center`,`Buddy Holly Center`), acts:[
    {id:'statue', n:t(`在名人步道上走走`,`Walk the Walk of Fame`,`Percorrer o Passeio da Fama`), cost:1, tip:t(`拉伯克出过的音乐人比你想的多`,`Lubbock has produced more musicians than you'd think`,`Lubbock deu mais músicos do que pensas`),
     run:()=>{stat('charme',1);stat('tex',1);return say(t(`名人步道`,`Walk of Fame`,`Passeio da Fama`),[t(`地上一块块铜牌，刻着从这片平原走出去的音乐人。一个老太太告诉你：“这儿除了风和棉花什么都没有，所以孩子们只能弹琴。”`,`Bronze plaques in the pavement name the musicians who came off these plains. An old lady tells you, "There's nothing out here but wind and cotton, so the kids play guitar."`,`Placas de bronze no chão com os nomes dos músicos que saíram destas planícies. Uma senhora diz-te: «Aqui não há nada além de vento e algodão, por isso os miúdos tocam guitarra.»`),...(W()==='kyle'?[t(`凯尔在铜像前站了很久，一句话也没说，最后摘下帽子。`,`Kyle stands in front of the statue for a long time without a word, and finally takes off his hat.`,`O Kyle fica muito tempo diante da estátua sem dizer nada e por fim tira o chapéu.`)]:W()?[t(`${WN()}在铜像旁边学巴迪·霍利推眼镜，被路过的游客拍了下来。`,`${WN()} copies Buddy Holly pushing up his glasses beside the statue and gets photographed by passing tourists.`,`${WN()} imita o Buddy Holly a ajeitar os óculos ao lado da estátua e é fotografado por turistas.`)]:[])],t(`魅力 +1 · 德州味 +1`,`Charm +1 · Texanness +1`,`Charme +1 · Texanidade +1`))}},
    {id:'wes', n:t(`找韦斯`,`Find Wes`,`Procurar o Wes`), cost:2, req:arcReq('wes','lubbock'), tip:t(`雕像下弹琴的学生`,`The student with a guitar under the statue`,`O estudante de guitarra debaixo da estátua`), run:wesScene}
   ]},
   {id:'tx4_tech', n:t(`德州理工大学`,`Texas Tech University`,`Universidade Texas Tech`), acts:[
    {id:'gameday', n:t(`球赛日停车场摆摊`,`Game-day tailgate stall`,`Banca no parque no dia de jogo`), cost:3, req:()=>!gameDay()?t(`只在橄榄球季（第 13–24 周）`,`Football season only (weeks 13–24)`,`Só na época de futebol americano (semanas 13–24)`):today('ttgame')?t(`今天已经摆过了`,`Already done today`,`Já fizeste isso hoje`):true, tip:t(`几万人的车尾派对`,`A tailgate of tens of thousands`,`Uma festa de parque com dezenas de milhares`),
     run:()=>{mark('ttgame');const r=popupSell(22,1.3);S.rep+=2;stat('tex',2);return say(t(`琼斯体育场外`,`Outside Jones Stadium`,`À porta do Estádio Jones`),[t(`红黑两色的海洋。戴面具的骑手骑着黑马冲进球场，人群把玉米饼往天上扔——这是这里的老传统，别问为什么。你的烤架前排起了长队。`,`A sea of red and black. The Masked Rider gallops onto the field on a black horse, and the crowd throws tortillas into the air — an old tradition here; don't ask why. A long line forms at your grill.`,`Um mar vermelho e preto. O Cavaleiro Mascarado entra a galope num cavalo preto e a multidão atira tortilhas ao ar — uma velha tradição daqui; não perguntes porquê. Forma-se uma fila comprida à tua grelha.`),sellLine(r)],t(`口碑 +2 · 德州味 +2`,`Reputation +2 · Texanness +2`,`Reputação +2 · Texanidade +2`))}},
    {id:'campus', n:t(`在校园里逛`,`Stroll the campus`,`Passear pelo campus`), cost:1, tip:t(`红瓦屋顶、钟楼`,`Red-tile roofs and a bell tower`,`Telhados vermelhos e uma torre sineira`),
     run:()=>{stat('saud',1);stat('oficio',1);return say(t(`校园`,`Campus`,`Campus`),[t(`钟楼报时，红瓦屋顶在大平原的太阳下像一片南欧小镇。你想起里斯本大学城，想起你没读完的那个学位。`,`The bell tower strikes the hour, and under the plains sun the red-tile roofs look like a southern European town. You think of the university city in Lisbon, and the degree you never finished.`,`A torre sineira dá as horas e, ao sol das planícies, os telhados vermelhos parecem uma vila do sul da Europa. Lembras-te da Cidade Universitária de Lisboa e do curso que nunca acabaste.`)],t(`乡愁 +1 · 手艺 +1`,`Homesickness +1 · Craft +1`,`Saudade +1 · Ofício +1`))}}
   ]},
   {id:'tx4_plains', n:t(`风车与棉田`,`Windmills & cotton fields`,`Moinhos e algodão`), acts:[
    {id:'mill', n:t(`参观美国风车博物馆`,`Visit the American Windmill Museum`,`Visitar o Museu Americano do Moinho de Vento`), cost:2, tip:t(`上百架老风车`,`Over a hundred old windmills`,`Mais de cem moinhos antigos`),
     run:()=>{stat('tex',2);stat('saud',-1);return say(t(`风车博物馆`,`Windmill museum`,`Museu do moinho`),[t(`上百架老式风车，有木头的，有铁皮的，一架比一架高。讲解员说，没有这些风车把地下水抽上来，大平原上就没有牧场，没有铁路，也没有拉伯克。你想起葡萄牙山头上那种白色圆身、布帆的老风磨——一样的风，不一样的活。`,`More than a hundred old windmills, wooden and steel, each taller than the last. The guide says without these mills pumping up groundwater there'd have been no ranches on the plains, no railroad, no Lubbock. You think of the old white round-bodied mills with cloth sails on Portuguese hilltops — same wind, different work.`,`Mais de cem moinhos antigos, de madeira e de ferro, cada um mais alto do que o outro. O guia diz que sem estes moinhos a tirar água do subsolo não teria havido ranchos nas planícies, nem caminho de ferro, nem Lubbock. Lembras-te dos velhos moinhos brancos de velas de pano nos montes de Portugal — o mesmo vento, outro trabalho.`)],t(`德州味 +2 · 乡愁 −1`,`Texanness +2 · Homesickness −1`,`Texanidade +2 · Saudade −1`))}},
    {id:'coop', n:t(`去农场合作社买货`,`Buy from a farm co-op`,`Comprar numa cooperativa agrícola`), cost:2, req:ONCE('lbcoop'), tip:t(`猪肉和蛋奶，收获季更便宜`,`Pork and eggs & milk; cheaper at harvest`,`Porco, ovos e leite; mais barato na colheita`),
     run:()=>{mark('lbcoop');const m=harvest()?0.6:0.72;const a=cityBuy('pork',15,m),b=cityBuy('dairy',20,m);
      return say(t(`农场合作社`,`Farm co-op`,`Cooperativa agrícola`),[t(`铁皮仓库里，几个农场主坐在饲料袋上聊棉价。${harvest()?'收获季大家手头宽，价钱也松。':'他们听说你从圣鲁伊斯开了三百英里来买猪肉，觉得你不是疯子就是认真。'}`,`In a tin warehouse a few farmers sit on feed sacks talking cotton prices. ${harvest()?'It\'s harvest; everyone\'s flush and prices are loose.':'When they hear you drove three hundred miles from San Luís for pork, they decide you\'re either crazy or serious.'}`,`Num armazém de chapa, uns lavradores sentados em sacos de ração falam do preço do algodão. ${harvest()?'É a colheita; toda a gente tem dinheiro e os preços estão soltos.':'Quando sabem que fizeste trezentas milhas desde San Luís por causa de porco, concluem que és maluco ou sério.'}`),buyLine(a,15,ING.pork.n),buyLine(b,20,ING.dairy.n)],t(`经营 · 采购`,`Business · buying`,`Negócio · compras`))}}
   ]}
  ]
 }
});

/* ================= AMARILLO ================= */
const showSeason=()=>inSeason(1,12);
const DUSTY=['达斯蒂·卡洛韦','Dusty Calloway','Dusty Calloway'];
const dustyScene=()=>{const s=stg('dusty'),C='amarillo',D='dusty';
 if(s>=4)return hang(D,[
  [[t(`达斯蒂在拍卖台上看见你，一边喊价一边冲你挤眼：“……那位葡萄牙先生不许举手！”全场哄笑。`,`Dusty spots you from the auction stand and winks mid-chant: "...and the Portuguese gentleman keeps his hands DOWN!" The whole barn laughs.`,`O Dusty vê-te do palanque e pisca-te o olho a meio da lengalenga: «...e o senhor português mantém as mãos em BAIXO!» O pavilhão inteiro ri-se.`)],()=>stat('tex',1)],
  [[t(`他请你吃了一盘牛排，问你冷库够不够大。“下个月那批阉牛特别好，我给你留最好的。”`,`He buys you a steak and asks if your cold room's big enough. "Next month's steers are real good. I'll hold you the best."`,`Paga-te um bife e pergunta se a tua câmara frigorífica é grande que chegue. «Os novilhos do mês que vem são bons a sério. Guardo-te os melhores.»`)],()=>stat('oficio',1)]]);
 if(s===0)return {title:t(`拍卖场`,`The sale barn`,`O pavilhão de leilões`),meta:metaArc(D),
  text:[t(`城东的牲畜拍卖每周开好几场，一圈一圈的木看台围着中间的沙地。拍卖师的嘴快得像机关枪，你一个字也听不懂。你抬手挠了挠耳朵——锤子落下。“卖给后排那位戴金表的先生！四十头阉牛！”全场转过头来看你。`,`The livestock auction on the east side runs several sales a week: tiers of wooden bleachers round a sand ring. The auctioneer's mouth goes like a machine gun and you can't follow a word. You lift a hand to scratch your ear — the gavel drops. "SOLD to the gentleman in the back with the gold watch! Forty head of steers!" The whole barn turns to look at you.`,`O leilão de gado do lado leste faz várias vendas por semana: bancadas de madeira à volta de uma arena de areia. O leiloeiro fala como uma metralhadora e não percebes uma palavra. Levantas a mão para coçar a orelha — o martelo cai. «VENDIDO ao senhor lá atrás do relógio dourado! Quarenta cabeças de novilhos!» O pavilhão inteiro vira-se para ti.`)],
  choices:[
   {t:t(`用葡语大喊“不不不”`,`Shout "no, no, no" in Portuguese`,`Gritar «não, não, não»`),fx:step(D,C,()=>{addLike(D,2);stat('tex',1)}),next:()=>say(t(`达斯蒂·卡洛韦`,`Dusty Calloway`,`Dusty Calloway`),t(`拍卖师笑得差点从台上掉下来，把那一锤作废了。散场后他来找你：“达斯蒂·卡洛韦。在这儿喊了三十年价，头一回有人用外语退货。你哪儿来的？”你说圣鲁伊斯。“圣鲁伊斯？那不是贝托·雷耶斯的地盘吗！”`,`The auctioneer nearly falls off the stand laughing and voids the sale. Afterwards he finds you. "Dusty Calloway. Thirty years calling sales and that's the first refund in a foreign language. Where you from?" San Luís, you say. "San Luís? That's Beto Reyes country!"`,`O leiloeiro quase cai do palanque a rir e anula a venda. No fim vem ter contigo. «Dusty Calloway. Trinta anos a fazer leilões e é a primeira devolução numa língua estrangeira. De onde és?» San Luís, dizes. «San Luís? Isso é terra do Beto Reyes!»`))},
   {t:t(`硬着头皮说：“我是开烧烤店的，买不下四十头，能买四十斤吗？”`,`Brazen it out: "I run a grill. I can't take forty head — can I take forty pounds?"`,`Aguentar firme: «Tenho uma churrasqueira. Não levo quarenta cabeças — posso levar quarenta quilos?»`),req:()=>S.stats.tex>=30||NEED(t(`德州味 30`,`Texanness 30`,`Texanidade 30`)),fx:step(D,C,()=>{addLike(D,1);addTrust(D,2);S.rep+=1}),next:()=>say(t(`达斯蒂·卡洛韦`,`Dusty Calloway`,`Dusty Calloway`),t(`全场大笑，有人鼓掌。拍卖师把锤子作废，散场后拍着你的肩：“有胆子。达斯蒂·卡洛韦。开烧烤的？从哪儿来？”听说是圣鲁伊斯，他眯起眼：“贝托·雷耶斯还活着吗？我二十年前卖过他爷爷的小牛。”`,`The barn roars; somebody claps. The auctioneer voids the sale and afterwards slaps your shoulder. "You got nerve. Dusty Calloway. A grill, huh? From where?" When he hears San Luís he squints. "Beto Reyes still kicking? I sold his granddaddy's calves twenty years back."`,`O pavilhão vem abaixo; alguém aplaude. O leiloeiro anula a venda e no fim dá-te uma palmada no ombro. «Tens coragem. Dusty Calloway. Uma churrasqueira, hã? De onde?» Quando ouve San Luís semicerra os olhos. «O Beto Reyes ainda anda por aí? Vendi os vitelos do avô dele há vinte anos.»`))}]};
 if(s===1)return {title:t(`凯迪拉克农场旁的试吃`,`A taste test by Cadillac Ranch`,`Uma prova junto ao Cadillac Ranch`),meta:metaArc(D),
  text:[t(`达斯蒂把皮卡停在 40 号州际公路边，十辆老凯迪拉克车头朝下插在麦田里，被喷漆喷得五颜六色。他从车斗里搬出一个小烤炉和一块牛排。“我帮狭长地带的几家育肥场卖牛。我不跟没尝过手艺的人做生意。烤吧。”`,`Dusty pulls his pickup over by I-40, where ten old Cadillacs stand nose-down in a wheat field, sprayed every colour there is. From the truck bed he lifts out a little grill and a steak. "I broker cattle for a few Panhandle feedlots. I don't do business with a man whose cooking I ain't tasted. Fire it up."`,`O Dusty encosta a carrinha junto à I-40, onde dez Cadillacs velhos estão espetados de nariz no chão num campo de trigo, pintados com todas as cores de spray. Da caixa tira um grelhador pequeno e um bife. «Vendo gado para umas quantas engordas do Panhandle. Não faço negócio com quem não provei a comida. Acende isso.»`),...(met('lucia')&&rel('lucia').trust>=3?[t(`“我听说你从雷耶斯家的姑娘那儿拿牛肉，”他补了一句，“我不抢她的生意。她没有的部位，我来。”`,`"I hear you get your beef off the Reyes girl," he adds. "I won't cut in on her. The cuts she don't have, those are mine."`,`«Ouvi dizer que compras a carne à filha dos Reyes», acrescenta. «Não lhe vou roubar o negócio. Os cortes que ela não tem, esses são meus.»`)]:[])],
  choices:[{t:t(`上烤架`,`Fire it up`,`Acender`),fx:step(D,C),next:()=>cityGrill(q=>{S.flags.tx4_dustyQ=q;if(q>=1.1){addLike(D,2);addTrust(D,2)}else addLike(D,1);stat('oficio',2);
    return say(t(`试吃`,`The verdict`,`O veredicto`),q>=1.1?t(`他嚼了很久，一句话不说，然后把剩下的半块用手抓着吃完了。“行。下次来，我们谈数字。”`,`He chews a long time without a word, then finishes the other half with his fingers. "All right. Next time you're up, we talk numbers."`,`Mastiga muito tempo sem dizer nada e depois acaba a outra metade à mão. «Está bem. Da próxima vez que vieres, falamos de números.»`):t(`“火大了点，”他说，“但你没往上抹番茄酱，这就值得再谈。下次来。”`,`"Little hot on the fire," he says, "but you didn't put ketchup on it, and that's worth another talk. Come back."`,`«Lume um bocado forte», diz ele, «mas não lhe puseste ketchup, e isso merece outra conversa. Volta.»`),t(`手艺 +2`,`Craft +2`,`Ofício +2`))})}]};
 if(s===2)return {title:t(`拍卖场办公室，旧账本`,`The sale-barn office, the old ledgers`,`O escritório do leilão, os livros antigos`),meta:metaArc(D),
  text:[t(`下雪天，拍卖停了。达斯蒂在办公室里翻九十年代的账本，手指停在一页上。“我一直想跟你说这个。博伊德，汉克·博伊德。1996 到 1998 年，每年春天来三四趟，专买最便宜的淘汰老母牛，一买几百头，全拉回圣鲁伊斯罐头厂。”`,`It's snowing and the sales are off. In the office Dusty leafs through ledgers from the nineties, and his finger stops on a page. "Been meaning to tell you this. Boyd. Hank Boyd. Ninety-six to ninety-eight, three or four trips every spring, buying the cheapest cull cows we had, hundreds at a time, all hauled back to the San Luís cannery."`,`Está a nevar e não há leilões. No escritório, o Dusty folheia livros de contas dos anos noventa e o dedo para numa página. «Há muito que te queria contar isto. Boyd. Hank Boyd. De noventa e seis a noventa e oito, três ou quatro idas todas as primaveras, a comprar as vacas de refugo mais baratas que tínhamos, centenas de cada vez, tudo levado para a fábrica de conservas de San Luís.»`),
   t(`“一个罐头厂一年处理那么多老牛，血和油总得有个去处。我当年没问。现在我老了，想问了。”`,`"A cannery running that many old cows a year — the blood and the fat have to go somewhere. I didn't ask back then. Now I'm old, and I'd like to."`,`«Uma fábrica a despachar tantas vacas velhas por ano — o sangue e a gordura têm de ir para algum lado. Na altura não perguntei. Agora estou velho e gostava de perguntar.»`)],
  choices:[
   {t:t(`请他复印这几页`,`Ask him to copy those pages`,`Pedir-lhe que fotocopie essas páginas`),fx:step(D,C,()=>{S.flags.tx4_ledger=1;addTrust(D,2);if(met('beto'))addTrust('beto',1);log('达斯蒂给了你汉克·博伊德买牛的旧账页','Dusty gave you the old ledger pages of Hank Boyd\'s cattle buys','O Dusty deu-te as páginas antigas das compras de gado do Hank Boyd')}),next:()=>say(t(`复印件`,`The copies`,`As cópias`),[t(`他亲手在每页上签了名和日期。“谁要是问，就说达斯蒂·卡洛韦愿意开车下去，当面说。”`,`He signs and dates every page by hand. "Anybody asks, you tell 'em Dusty Calloway'll drive down and say it to their face."`,`Assina e data cada página à mão. «Se alguém perguntar, diz que o Dusty Calloway desce lá e diz-lho na cara.»`),S.flags.evidence?t(`你想起铁柜里那份水质报告。现在，它有了一个伴。`,`You think of the water report from the iron locker. Now it has company.`,`Pensas no relatório da água do cacifo de ferro. Agora tem companhia.`):t(`你还没有若泽留下的证据，但这几页纸让你知道，那些事真的发生过。`,`You don't have José's evidence yet, but these pages tell you it all really happened.`,`Ainda não tens as provas do José, mas estas páginas dizem-te que tudo aconteceu mesmo.`)],t(`得到：汉克·博伊德的旧账页`,`Received: Hank Boyd's old ledger pages`,`Recebeste: as páginas antigas do Hank Boyd`))},
   {t:t(`告诉他特拉维斯现在想买你的地`,`Tell him Travis wants to buy your land now`,`Contar-lhe que o Travis agora quer comprar o teu terreno`),req:()=>met('travis')||NEED(t(`认识特拉维斯`,`Know Travis`,`Conhecer o Travis`)),fx:step(D,C,()=>{S.flags.tx4_ledger=1;addTrust(D,2);addLike(D,1)}),next:()=>say(t(`儿子`,`The son`,`O filho`),t(`达斯蒂沉默了。“特拉维斯去年打电话来，想用他爸的老关系从我这儿批牛，给他的油田工人开食堂。我挂了他的电话。”他把复印件推过来：“拿着。他爸欠下的，总得有人记着。”`,`Dusty goes quiet. "Travis called last year, wanting to use his daddy's old connection to buy beef off me for an oilfield canteen. I hung up on him." He slides the copies over. "Take 'em. What his daddy owed, somebody ought to remember."`,`O Dusty cala-se. «O Travis ligou-me no ano passado, a querer usar os contactos antigos do pai para me comprar carne para uma cantina de petrolíferos. Desliguei-lhe o telefone.» Empurra as cópias para ti. «Leva. O que o pai dele ficou a dever, alguém tem de se lembrar.»`),t(`得到：汉克·博伊德的旧账页 · 达斯蒂信任 +2`,`Received: Hank Boyd's ledger pages · Dusty's trust +2`,`Recebeste: as páginas do Hank Boyd · Confiança do Dusty +2`))},
]};
 const m=(S.flags.tx4_dustyQ||1)>=1.1?0.75:0.8;
 return {title:t(`帕洛杜罗峡谷边的握手`,`A handshake on the rim of Palo Duro`,`Um aperto de mão na borda do Palo Duro`),meta:metaArc(D),
  text:[t(`帕洛杜罗峡谷是全美第二大的峡谷，在平得像桌面的大平原上突然裂开，红色、橙色、白色一层一层往下。达斯蒂靠在皮卡上，把一张写着数字的纸递给你。“狭长地带的牛肉，每周一车，走 27 号和 35 号公路下去。比你现在进的价便宜，肉比你现在的好。条件只有一个：店名后面加一行小字——‘牛肉来自阿马里洛’。”`,`Palo Duro is the second-largest canyon in the country, splitting open without warning in plains flat as a tabletop, red and orange and white in layers all the way down. Dusty leans on his pickup and hands you a sheet with numbers on it. "Panhandle beef, a truckload a week, down 27 and I-35. Cheaper than what you're paying, better than what you're getting. One condition: under the shop's name, one little line — 'Beef from Amarillo.'"`,`O Palo Duro é o segundo maior desfiladeiro do país, rasga-se sem aviso numa planície lisa como um tampo de mesa, vermelho, laranja e branco em camadas até ao fundo. O Dusty encosta-se à carrinha e dá-te uma folha com números. «Carne do Panhandle, um camião por semana, pela 27 e pela I-35. Mais barata do que pagas, melhor do que a que tens. Uma só condição: debaixo do nome do restaurante, uma linha pequenina — "Carne de Amarillo".»`),...(met('beto')?[t(`“还有，替我跟贝托·雷耶斯说：他爷爷的小牛是我卖过最好的。”`,`"And tell Beto Reyes for me: his granddaddy's calves were the best I ever sold."`,`«E diz ao Beto Reyes por mim: os vitelos do avô dele foram os melhores que alguma vez vendi.»`)]:[])],
  choices:[
   {t:t(`握手成交`,`Shake on it`,`Apertar a mão`),fx:step(D,C,()=>{grantPerk('beef',m,DUSTY);addTrust(D,2);if(met('beto'))addLike('beto',1)}),next:()=>say(t(`成交`,`Deal`,`Negócio fechado`),t(`他的手又干又硬，像一块老马鞍。“在狭长地带，”他说，“握手比合同管用。合同会丢，手不会。”`,`His hand is dry and hard as an old saddle. "Up here," he says, "a handshake beats a contract. Contracts get lost. Hands don't."`,`A mão dele é seca e dura como uma sela velha. «Aqui em cima», diz ele, «um aperto de mão vale mais que um contrato. Os contratos perdem-se. As mãos não.»`),t(`长期供货：牛肉 ×${m} · 达斯蒂的故事完结`,`Supply deal: beef ×${m} · Dusty's story complete`,`Fornecimento: carne de vaca ×${m} · História do Dusty concluída`))},
   {t:t(`按狭长地带的规矩，往手心吐口唾沫再握`,`Do it the Panhandle way: spit in your palm and shake`,`À moda do Panhandle: cuspir na palma e apertar`),req:()=>S.stats.tex>=45||NEED(t(`德州味 45`,`Texanness 45`,`Texanidade 45`)),fx:step(D,C,()=>{grantPerk('beef',m,DUSTY);addLike(D,3);stat('tex',3)}),next:()=>say(t(`成交`,`Deal`,`Negócio fechado`),t(`达斯蒂大笑，也吐了一口。“老天，你比一半阿马里洛人都像阿马里洛人。”`,`Dusty roars and spits too. "Lord, you're more Amarillo than half of Amarillo."`,`O Dusty dá uma gargalhada e cospe também. «Valha-me Deus, és mais de Amarillo do que metade de Amarillo.»`),t(`长期供货：牛肉 ×${m} · 德州味 +3 · 达斯蒂的故事完结`,`Supply deal: beef ×${m} · Texanness +3 · Dusty's story complete`,`Fornecimento: carne de vaca ×${m} · Texanidade +3 · História do Dusty concluída`))},
   {t:t(`再压一压价`,`Push the price down further`,`Baixar mais o preço`),req:()=>S.stats.oficio>=45||NEED(t(`手艺 45`,`Craft 45`,`Ofício 45`)),fx:step(D,C,()=>{grantPerk('beef',Math.round((m-0.05)*100)/100,DUSTY);addLike(D,-1);addTrust(D,1)}),next:()=>say(t(`成交`,`Deal`,`Negócio fechado`),t(`他盯着你看了很久：“你舅舅也这样，抠到最后一分。”然后在纸上划掉一个数，写了个更小的。“就这一次。”`,`He stares at you a long while. "Your uncle was like that too — squeezed every last cent." Then he crosses out a number and writes a smaller one. "Just this once."`,`Fica muito tempo a olhar para ti. «O teu tio também era assim — espremia até ao último cêntimo.» Depois risca um número e escreve um mais pequeno. «Só desta vez.»`),t(`长期供货：牛肉 ×${Math.round((m-0.05)*100)/100} · 达斯蒂的故事完结`,`Supply deal: beef ×${Math.round((m-0.05)*100)/100} · Dusty's story complete`,`Fornecimento: carne de vaca ×${Math.round((m-0.05)*100)/100} · História do Dusty concluída`))}]};
};
Object.assign(CITIES,{
 amarillo:{
  n:t(`阿马里洛`,`Amarillo`,`Amarillo`), region:'north', miles:400, trip:'overnight', hotel:85,
  desc:t(`狭长地带的中心，66 号公路穿城而过。牛比人多，风比牛多，地平线上的风车数不过来。`,`The heart of the Panhandle, with old Route 66 running through it. More cattle than people, more wind than cattle, and more windmills on the horizon than you can count.`,`O coração do Panhandle, atravessado pela velha Route 66. Mais gado do que gente, mais vento do que gado e mais moinhos no horizonte do que consegues contar.`),
  arrive:()=>{const v=S.visited.amarillo||0;
   if(v<=1)return [t(`离城还有十英里你就闻到了——育肥场的味道。加油站的老头说：“这叫钱的味道，孩子。”`,`Ten miles out you smell it: the feedlots. The old man at the gas station says, "That's the smell of money, son."`,`A dez milhas da cidade já se sente: as engordas. O velho da bomba de gasolina diz: «É o cheiro do dinheiro, rapaz.»`)];
   return [inSeason(25,36)?t(`北风从大平原上直接刮下来，没有一棵树挡。你终于明白德州人说的“蓝色北风”是什么意思。`,`The north wind comes straight down off the plains with not a tree to stop it. You finally understand what Texans mean by a "blue norther."`,`O vento norte desce direitinho das planícies sem uma árvore que o pare. Finalmente percebes o que os texanos querem dizer com um «blue norther».`):t(`那股“钱的味道”又来了。你发现自己已经不皱眉了。`,`The "smell of money" again. You notice you've stopped wrinkling your nose.`,`Outra vez o «cheiro do dinheiro». Reparas que já não franzes o nariz.`)]},
  locs:[
   {id:'tx4_auction', n:t(`牲畜拍卖场`,`Livestock auction`,`Leilão de gado`), acts:[
    {id:'dusty', n:t(`去看拍卖`,`Watch the auction`,`Ver o leilão`), cost:2, req:arcReq('dusty','amarillo'), tip:t(`千万别乱举手`,`Whatever you do, don't raise your hand`,`Faças o que fizeres, não levantes a mão`), run:dustyScene},
    {id:'bulk', n:t(`从屠宰分割场批牛肉`,`Buy beef off a packing floor`,`Comprar carne a um entreposto`), cost:2, req:ONCE('amabulk'), tip:t(`整批拿货，七折`,`Bulk, at 70%`,`Por atacado, a 70%`),
     run:()=>{mark('amabulk');return {title:t(`分割场`,`The packing floor`,`O entreposto`),meta:t(`经营 · 采购`,`Business · buying`,`Negócio · compras`),
      text:[t(`冷库门一开，白气扑出来。整片的牛胸肉挂成一排，工人们说话像吵架。${met('dusty')?'领班看见你就喊：“达斯蒂的人？那再便宜一点。”':'领班上下打量你：“开烧烤的？量大才有价。”'}`,`The cold-room door opens in a gust of white vapour. Whole briskets hang in a row and the workers talk like they're arguing. ${met('dusty')?'The foreman sees you and shouts, "Dusty\'s guy? Then a little cheaper."':'The foreman looks you over. "Grill man? Price comes with volume."'}`,`A porta da câmara abre-se num bafo de vapor branco. Peitos de vaca inteiros pendurados em fila e os trabalhadores falam como se discutissem. ${met('dusty')?'O encarregado vê-te e grita: «És do Dusty? Então mais baratinho.»':'O encarregado mede-te. «Churrasqueiro? O preço vem com a quantidade.»'}`)],
      choices:[
       {t:t(`买 10 份牛肉`,`Buy 10 units of beef`,`Comprar 10 unidades de carne de vaca`),fx:()=>{S.flags.tx4_amc=cityBuy('beef',10,met('dusty')?0.65:0.7)},next:()=>say(t(`装车`,`Loading up`,`Carregar`),buyLine(S.flags.tx4_amc,10,ING.beef.n))},
       {t:t(`买 20 份，冰柜塞满`,`Buy 20 and pack the freezer`,`Comprar 20 e encher a arca`),req:()=>S.cash>=200||NEED(t(`现金 $200`,`$200 cash`,`$200 em dinheiro`)),fx:()=>{S.flags.tx4_amc=cityBuy('beef',20,met('dusty')?0.62:0.68)},next:()=>say(t(`装车`,`Loading up`,`Carregar`),buyLine(S.flags.tx4_amc,20,ING.beef.n))},
       {t:t(`只看不买`,`Just look`,`Só ver`)}]}}}
   ]},
   {id:'tx4_route66', n:t(`66 号公路老街`,`Route 66 on Sixth Street`,`A Route 66 na Sixth Street`), acts:[
    {id:'diner', n:t(`在老餐馆学炸牛排`,`Learn chicken-fried steak at an old diner`,`Aprender bife panado num diner antigo`), cost:2, req:()=>S.flags.dish_tx4_cfs?t(`已经学会了`,`Already learned`,`Já aprendeste`):true, tip:t(`德州人的周日午饭`,`Texas's Sunday dinner`,`O almoço de domingo do Texas`),
     run:()=>({title:t(`六街老餐馆`,`An old diner on Sixth`,`Um diner antigo na Sixth`),meta:t(`学新菜`,`New dish`,`Prato novo`),
      text:[t(`六街是 66 号公路穿过阿马里洛的老路段，红砖铺面、霓虹招牌、卖旧车牌的小店。街角一家老餐馆，厨娘把一块牛排拍薄，裹面粉、蛋液、再裹面粉，下油锅炸得金黄，浇上一大勺胡椒白肉汁。“这叫炸鸡式牛排，里头没有鸡。别问。”`,`Sixth Street is the old stretch of Route 66 through Amarillo: red-brick storefronts, neon signs, little shops selling old licence plates. In a corner diner the cook pounds a steak thin, dredges it in flour, egg, flour again, fries it golden and drowns it in a ladle of peppery cream gravy. "It's called chicken-fried steak. There's no chicken in it. Don't ask."`,`A Sixth Street é o troço antigo da Route 66 em Amarillo: montras de tijolo vermelho, néones, lojinhas de matrículas antigas. Num diner de esquina, a cozinheira bate um bife até ficar fino, passa-o por farinha, ovo e farinha outra vez, frita-o até ficar dourado e afoga-o numa concha de molho branco com pimenta. «Chama-se chicken-fried steak. Não tem frango. Não perguntes.»`),t(`你想起里斯本的炸猪排，几乎一样的手法。原来全世界的穷人都知道，薄一点、炸一下，便宜的肉也能吃得像过节。`,`You think of the breaded cutlets back in Lisbon — nearly the same technique. Poor people the world over know: pound it thin, fry it, and cheap meat tastes like a holiday.`,`Lembras-te dos panados de Lisboa — quase a mesma técnica. Os pobres do mundo inteiro sabem: bate-se fino, frita-se, e a carne barata sabe a dia de festa.`)],
      choices:[
       {t:t(`系上围裙学一上午`,`Put on an apron and learn all morning`,`Pôr o avental e aprender a manhã inteira`),fx:()=>{learnDish('tx4_cfs');stat('oficio',2);stat('tex',2)},next:()=>say(t(`炸牛排`,`Chicken-fried steak`,`Bife panado`),t(`她说秘诀是油温和耐心，还有肉汁里那一大把黑胡椒。“卡车司机会为了这个绕路五十英里。”`,`She says the secret is oil temperature and patience — and a big fistful of black pepper in the gravy. "Truckers'll drive fifty miles out of their way for this."`,`Diz que o segredo é a temperatura do óleo e paciência — e uma boa mão-cheia de pimenta preta no molho. «Os camionistas desviam-se cinquenta milhas por isto.»`),t(`学会：炸牛排配白肉汁 · 手艺 +2 · 德州味 +2`,`Learned: Chicken-fried steak · Craft +2 · Texanness +2`,`Aprendeste: Bife panado à texana · Ofício +2 · Texanidade +2`))},
       {t:t(`教她用葡式腌法，换她的肉汁方子`,`Trade her the Portuguese marinade for her gravy recipe`,`Trocar-lhe a marinada portuguesa pela receita do molho`),req:()=>S.stats.oficio>=35||NEED(t(`手艺 35`,`Craft 35`,`Ofício 35`)),fx:()=>{learnDish('tx4_cfs');stat('oficio',3);S.rep+=2},next:()=>say(t(`交换`,`A trade`,`Uma troca`),t(`蒜、白葡萄酒、红椒粉。她尝了一口你腌的肉，把肉汁方子写在点单本上撕给你：“下礼拜我就把这个加进菜单，名字叫‘里斯本炸牛排’。”`,`Garlic, white wine, paprika. She tastes your marinated steak, writes the gravy recipe on her order pad and tears it off for you. "Next week this goes on my menu. I'm calling it Lisbon fried steak."`,`Alho, vinho branco, colorau. Prova o teu bife marinado, escreve a receita do molho no bloco de pedidos e arranca-a para ti. «Para a semana ponho isto na ementa. Vai chamar-se bife frito de Lisboa.»`),t(`学会：炸牛排配白肉汁 · 手艺 +3 · 口碑 +2`,`Learned: Chicken-fried steak · Craft +3 · Reputation +2`,`Aprendeste: Bife panado à texana · Ofício +3 · Reputação +2`))}]})},
    {id:'cadillac', n:t(`去凯迪拉克农场喷漆`,`Spray-paint at Cadillac Ranch`,`Pintar com spray no Cadillac Ranch`), cost:1, tip:t(`十辆车头朝下插在地里的老凯迪拉克`,`Ten old Cadillacs buried nose-first in a field`,`Dez Cadillacs velhos enterrados de nariz num campo`),
     run:()=>({title:t(`凯迪拉克农场`,`Cadillac Ranch`,`Cadillac Ranch`),meta:t(`1974 年的露天艺术`,`Open-air art since 1974`,`Arte ao ar livre desde 1974`),
      text:[t(`十辆老凯迪拉克从 1974 年起就头朝下插在麦田里，尾鳍朝天。谁都可以来喷漆，漆一层盖一层，据说已经厚得像树皮。地上全是空喷罐。`,`Since 1974 ten old Cadillacs have stood nose-down in a wheat field, tail fins to the sky. Anyone can spray-paint them; the layers are said to be as thick as tree bark by now. The ground is littered with empty cans.`,`Desde 1974 que dez Cadillacs velhos estão de nariz enterrado num campo de trigo, com as barbatanas para o céu. Qualquer pessoa os pode pintar; dizem que as camadas já são grossas como casca de árvore. O chão está cheio de latas vazias.`)],
      choices:[
       {t:t(`喷上“若泽烧烤店，35 号州际公路”`,`Spray "Zé's Churrasco, I-35"`,`Pintar «Zé's Churrasco, I-35»`),fx:()=>{S.online+=2;stat('charme',1)},next:()=>say(t(`喷漆`,`Spray paint`,`Spray`),t(`你写得歪歪扭扭。十分钟后一个德国游客就在上面喷了一颗心。照片传上网，有人留言：“下周去吃。”`,`Your letters wobble. Ten minutes later a German tourist sprays a heart over it. The photo goes online and somebody comments: "Going next week."`,`As letras saem tortas. Dez minutos depois um turista alemão pinta um coração por cima. A fotografia vai parar à internet e alguém comenta: «Vou lá para a semana.»`),t(`线上评分 +2 · 魅力 +1`,`Online +2 · Charm +1`,`Online +2 · Charme +1`))},
       {t:t(`和${WN()}一起把两个名字喷在同一辆车上`,`Spray both your names on the same car with ${WN()}`,`Pintar os vossos dois nomes no mesmo carro com ${WN()}`),req:NEEDW,fx:()=>{if(W()){addLike(W(),2)}stat('saud',-2)},next:()=>say(t(`喷漆`,`Spray paint`,`Spray`),t(`${WN()}说：“明天就会被别人盖掉。”你说：“那也在下面。”你们站在风里看了很久那层油漆。`,`${WN()} says, "Someone'll paint over it tomorrow." You say, "It'll still be underneath." You stand in the wind looking at the paint a long time.`,`${WN()} diz: «Amanhã alguém pinta por cima.» Tu dizes: «Fica por baixo na mesma.» Ficam muito tempo ao vento a olhar para a tinta.`),t(`好感 +2 · 乡愁 −2`,`Affection +2 · Homesickness −2`,`Afeto +2 · Saudade −2`))}]})}
   ]},
   {id:'tx4_paloduro', n:t(`帕洛杜罗峡谷`,`Palo Duro Canyon`,`Desfiladeiro de Palo Duro`), acts:[
    {id:'lighthouse', n:t(`走到灯塔岩`,`Hike to the Lighthouse`,`Caminhar até ao Farol`), cost:3, req:DAY, tip:t(`峡谷里一根孤零零的红石柱`,`A lone red rock tower in the canyon`,`Uma torre solitária de rocha vermelha`),
     run:()=>{stat('tex',2);stat('saud',-2);return say(t(`灯塔岩`,`The Lighthouse`,`O Farol`),[t(`走了三个钟头，红土小径尽头立着一根石柱，像一座灯塔。你从来没想过，离海一千多公里的地方会有一座灯塔。你在下面坐着，想起卡斯凯什的灯塔和外公的船。`,`Three hours along the red-dirt trail and at the end stands a rock pillar shaped like a lighthouse. You never imagined finding a lighthouse more than a thousand kilometres from the sea. You sit beneath it and think of the lighthouse at Cascais, and your grandfather's boat.`,`Três horas pelo trilho de terra vermelha e no fim ergue-se um pilar de rocha com a forma de um farol. Nunca imaginaste encontrar um farol a mais de mil quilómetros do mar. Sentas-te por baixo e pensas no farol de Cascais e no barco do teu avô.`)],t(`德州味 +2 · 乡愁 −2`,`Texanness +2 · Homesickness −2`,`Texanidade +2 · Saudade −2`))}},
    {id:'show', n:t(`露天剧场外摆摊`,`Stall outside the amphitheater`,`Banca à porta do anfiteatro`), cost:3, req:()=>!showSeason()?t(`只在夏天的演出季（第 1–12 周）`,`Summer show season only (weeks 1–12)`,`Só na época de espetáculos de verão (semanas 1–12)`):today('pdshow')?t(`今天已经摆过了`,`Already done today`,`Já fizeste isso hoje`):true, tip:t(`峡谷里的夏夜音乐剧《德克萨斯》`,`The summer-night musical TEXAS in the canyon`,`O musical de verão TEXAS no desfiladeiro`),
     run:()=>{mark('pdshow');const r=popupSell(18,1.3);S.rep+=1;stat('tex',1);return say(t(`峡谷剧场`,`The canyon theater`,`O teatro do desfiladeiro`),[t(`每年夏天，峡谷底的露天剧场演一出叫《德克萨斯》的音乐剧，崖壁就是布景，最后一幕有骑手举着州旗从崖顶跑过。散场的观众饿得很，你的炭火是峡谷里唯一的灯。`,`Every summer the open-air amphitheater on the canyon floor stages a musical called TEXAS; the cliff is the backdrop, and in the last scene a rider gallops along the rim with the state flag. The crowd comes out starving, and your coals are the only light in the canyon.`,`Todos os verões o anfiteatro ao ar livre no fundo do desfiladeiro leva à cena um musical chamado TEXAS; a falésia é o cenário e, na última cena, um cavaleiro galopa pela borda com a bandeira do estado. O público sai esfomeado e as tuas brasas são a única luz no desfiladeiro.`),sellLine(r)],t(`快闪摊 · 德州味 +1`,`Pop-up · Texanness +1`,`Banca · Texanidade +1`))}}
   ]}
  ]
 }
});
})();
